/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A42 staging source: frozen manifest hamburger–harmony; checkpoints audited in 20-word slices. */
'use strict';
const D=globalThis.RA.D;
const E=(origin,word)=>({origin,prefix:null,root:null,suffix:null,history:[],formationLogic:'',mnemonic:null,note:'Claims are limited to the stated formation; uncertain history is left open.',source:'Etymonline — https://www.etymonline.com/word/'+word.toLowerCase()});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(w,n,s,prompt,a,b,c,answer,explain,errorType='meaning')=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType,type:'辨义与用法',prompt,options:[a,b,c],answer,explain});

D('hamburger',{etymology:E('Hamburger is named for Hamburg, Germany; the food name came through Hamburg steak, a minced-beef dish associated with the port city. In modern English it commonly means a beef patty in a bun, the patty alone, or minced beef.','hamburger'),contexts:[C('hamburger.s2','家庭烹饪','For the picnic, Luis grilled each hamburger patty until it was browned outside and safely cooked through, then let it rest before serving.','野餐时，路易斯把每块汉堡肉饼烤到外面焦黄、里面熟透，然后静置片刻再上桌。','For the picnic / Luis grilled each hamburger patty / until it was browned outside / and safely cooked through.','hamburger 在此指夹入面包前的碎牛肉饼。','句中明确写 hamburger patty，匹配 s2。')],mistakes:[M('The vegetarian grill menu listed a hamburger made only from minced beef as a meat-free bean patty.','The vegetarian grill menu listed a bean patty, while the hamburger contained minced beef.','含碎牛肉的汉堡不是纯豆制的无肉肉饼。')],quiz:[Q('hamburger',1,1,'A hamburger served in a bun is usually?','a cooked minced-beef patty in bread','a sweet orange','a small village','a cooked minced-beef patty in bread','s1 指夹在面包中的牛肉饼。'),Q('hamburger',2,2,'At a butcher’s counter, a hamburger may mean?','a flat fried minced-beef patty','a clock hand','a travel guide','a flat fried minced-beef patty','s2 指煎制的碎牛肉饼。'),Q('hamburger',3,3,'In a recipe, “add 300 grams of hamburger” may mean?','minced beef','a bread bun only','a frying pan','minced beef','s3 可指绞碎的牛肉。'),Q('hamburger',4,1,'The name hamburger is historically associated with?','Hamburg','Hampshire','Hamlin','Hamburg','hamburger 由 Hamburg 相关名称发展而来。','word-formation')]});
D('hamlet',{etymology:E('Hamlet came through Old French hamelet, a diminutive of hamel “village,” ultimately from a Germanic word related to home. It means a very small village.','hamlet'),contexts:[C('hamlet.s1','乡村地理','The bus left the market town at noon and stopped at a hamlet of twelve houses clustered around a stone chapel.','公交车中午离开集镇，在一座仅有十二户人家、围绕石头礼拜堂聚集的小村庄停靠。','The bus left the market town at noon / and stopped at a hamlet / of twelve houses / clustered around a stone chapel.','hamlet 指规模很小的村庄。','只有少数房屋围绕礼拜堂，符合小村落义。')],mistakes:[M('The hamlet was a metropolis of millions of residents, with a dense subway network and skyscrapers.','The hamlet was a tiny rural settlement with only a few houses.','人口数百万、拥有地铁和摩天楼的城市不能称为 hamlet。')],quiz:[Q('hamlet',1,1,'A hamlet is usually?','a very small village','a large capital city','a type of hand tool','a very small village','hamlet 指很小的村庄。'),Q('hamlet',2,1,'Which place is most likely a hamlet?','a dozen homes around a country chapel','a city of five million people','an industrial port with 30 districts','a dozen homes around a country chapel','少量住宅组成的乡村聚落符合 hamlet。'),Q('hamlet',3,1,'A hamlet differs from a metropolis mainly in its?','small size and rural character','use of clock hands','number of handbooks','small size and rural character','hamlet 的规模通常很小。'),Q('hamlet',4,1,'The suffix in the historical French form hamelet was diminutive, suggesting?','a small settlement','a royal palace','a fast-moving machine','a small settlement','词源中的小称形式与“小村庄”义相符。','word-formation')]});
D('hamlin',{etymology:E('Hamlin is a proper-name form used as a family name and as the name of an early orange cultivar. The deeper origin of the cultivar label is not stated here because it is uncertain.','hamlin'),contexts:[C('hamlin.s2','果园采收','The grower picked Hamlin oranges early in the season, sorting the sweet fruit for juice before the later cultivars were ready.','种植者在季节较早时采收哈姆林甜橙；其他品种成熟前，他先把这种甜橙分拣出来榨汁。','The grower picked Hamlin oranges early in the season / sorting the sweet fruit for juice / before the later cultivars / were ready.','Hamlin 在此是早熟甜橙品种名。','早季成熟、适于榨汁的橙子对应 s2。')],mistakes:[M('The orchard labeled its Hamlin crop as a late-ripening, bitter lemon variety.','The orchard labeled its Hamlin crop as an early sweet orange variety.','Hamlin 指早熟甜橙品种，不是晚熟苦味柠檬。')],quiz:[Q('hamlin',1,1,'Hamlin used as a surname is?','a family name','a type of hammer','a village size','a family name','s1 指姓氏或出现在专名中的形式。'),Q('hamlin',2,2,'A Hamlin orange is known as?','an early sweet orange cultivar','a bitter late lemon','a small rodent','an early sweet orange cultivar','s2 指早熟甜橙。'),Q('hamlin',3,2,'A grower might harvest Hamlin oranges?','early in the season','only after the fruit freezes','from a hand-operated tool','early in the season','该品种以较早成熟著称。'),Q('hamlin',4,1,'Which use is a proper-name use of Hamlin?','a person’s family name','a generic name for all citrus','a verb meaning to hit nails','a person’s family name','Hamlin 可用作姓氏。')]});
D('hammer',{etymology:E('Hammer comes from Old English hamor, from a Germanic word for a striking tool. It can name the tool, a striking part in a piano or firearm, the act of hitting or forceful criticism, or an auction mallet and throwing event.','hammer'),contexts:[C('hammer.s4','新闻评论','During the hearing, the senator hammered the agency over its repeated failure to publish safety reports on time.','听证会上，参议员就该机构屡次未能按时公布安全报告一事对其进行了猛烈抨击。','During the hearing / the senator hammered the agency / over its repeated failure / to publish safety reports on time.','hammered 在此是动词，比喻猛烈批评、反复施压。','围绕反复失职展开严厉质问，符合 s4。')],mistakes:[M('The reviewer hammered the proposal by praising every part of it and raising no criticism.','The reviewer praised the proposal without hammering it.','完全赞扬且没有批评，与猛烈抨击的比喻义相反。')],quiz:[Q('hammer',1,1,'A carpenter uses a hammer to?','strike nails','measure a village','store food in cheek pouches','strike nails','s1 指敲钉子的工具。'),Q('hammer',2,2,'A piano hammer is the part that?','strikes a string','holds the instrument’s handle','controls a car engine','strikes a string','s2 指钢琴内敲击琴弦的部件。'),Q('hammer',3,4,'To hammer a company over a failure is to?','criticize it forcefully and repeatedly','give it a laundry basket','hand it a travel guide','criticize it forcefully and repeatedly','s4 可表示猛烈批评或反复强调。'),Q('hammer',4,5,'At an auction, the hammer is?','the mallet used to signal a sale','the orange fruit on the table','a hand-operated drill','the mallet used to signal a sale','s5 可指拍卖槌。')]});
D('hammerhead',{etymology:E('Hammerhead combines hammer and head, describing either the metal striking head of a hammer or the shark whose broad, flattened head resembles one.','hammerhead'),contexts:[C('hammerhead.s2','海洋生物','The diver watched a hammerhead pass over the sandy seabed, its broad head and widely spaced eyes unmistakable against the blue water.','潜水员看着一条双髻鲨掠过沙质海床；它宽扁的头部和分布两端的眼睛在蓝水中十分醒目。','The diver watched a hammerhead pass over the sandy seabed / its broad head / and widely spaced eyes / unmistakable against the blue water.','hammerhead 在此指双髻鲨。','宽扁头部两端长眼是该鲨鱼的特征。')],mistakes:[M('The hammerhead shark had a narrow pointed head with both eyes directly beside its nose.','The hammerhead shark had a broad head with eyes near its outer ends.','双髻鲨以横向宽扁、两眼分居两端的头部为特征。')],quiz:[Q('hammerhead',1,1,'The hammerhead of a tool is?','its heavy striking head','the handle held in the palm','a cloth basket','its heavy striking head','s1 指锤子的金属头部。'),Q('hammerhead',2,2,'A hammerhead is a shark named for its?','wide flattened head','orange colour','ability to live in a village','wide flattened head','s2 指头部像锤头的鲨鱼。'),Q('hammerhead',3,2,'A diver identifies a hammerhead by its eyes?','set near the ends of a broad head','hidden under a shell','located on its tail','set near the ends of a broad head','双髻鲨的眼睛位于宽头两端附近。'),Q('hammerhead',4,1,'Which part of a hammer is its hammerhead?','the metal part that strikes','the cord wrapped around the grip','the nail being driven','the metal part that strikes','工具义指金属敲击部位。')]});
D('hamper',{etymology:E('Hamper as a verb meaning hinder is recorded in Middle English, with its earlier history uncertain. The noun “basket” has a separate history and names a large food or laundry basket.','hamper'),contexts:[C('hamper.s1','施工现场','A shortage of replacement parts could hamper the bridge repair, forcing the crew to close another lane while they waited.','替换零件短缺可能会妨碍桥梁维修，迫使施工队在等待期间再封闭一条车道。','A shortage of replacement parts / could hamper the bridge repair / forcing the crew / to close another lane while they waited.','hamper 在此是动词，表示使事情更难推进。','零件短缺导致维修延误，符合 s1。')],mistakes:[M('The road closure hampered the repair by making every repair task easier and allowing crews to finish immediately.','The road closure hampered the repair by making access more difficult and delaying the crew.','使维修更容易且立即完成，不符合“妨碍”义。')],quiz:[Q('hamper',1,1,'A delay may hamper a project by?','making it harder to complete','making the work effortless','turning it into a basket','making it harder to complete','s1 表示妨碍、阻碍。'),Q('hamper',2,2,'A picnic hamper is a?','large basket for food','piece of a piano','small firearm','large basket for food','s2 指野餐等用的大篮子。'),Q('hamper',3,3,'A laundry hamper is used to hold?','dirty clothes','fresh oranges','auction hammers','dirty clothes','s3 指洗衣篮。'),Q('hamper',4,1,'Poor visibility can hamper a driver because it?','makes safe driving more difficult','stores food for a trip','improves the view','makes safe driving more difficult','视线不清会妨碍安全驾驶。')]});
D('hampshire',{etymology:E('Hampshire is an English county name formed with shire, an Old English word for an administrative district. The county name is historically associated with the settlement of Hamtun; details of the older place-name formation are not asserted here.','hampshire'),contexts:[C('hampshire.s1','英国地理','The family took the train through Hampshire and changed at Winchester, the county town, before continuing toward the south coast.','一家人乘火车穿过汉普郡，在郡治温切斯特换车后继续前往南海岸。','The family took the train through Hampshire / and changed at Winchester / the county town / before continuing toward the south coast.','Hampshire 是英格兰南部的郡名。','Winchester 是郡治，旅程位于英格兰南部。')],mistakes:[M('Winchester is the county town of Hampshire, a county located in northern Scotland.','Winchester is the county town of Hampshire, in southern England.','Hampshire 位于英格兰南部，不在苏格兰北部。')],quiz:[Q('hampshire',1,1,'Hampshire is a county in?','southern England','northern Scotland','western Canada','southern England','Hampshire 位于英格兰南部。'),Q('hampshire',2,1,'What is the county town of Hampshire?','Winchester','Hamlin','Hamburg','Winchester','郡治是 Winchester。'),Q('hampshire',3,1,'In Hampshire, shire historically means?','an administrative district','a small orange','a hammer part','an administrative district','shire 指郡或行政区。','word-formation'),Q('hampshire',4,1,'Which travel description fits Hampshire?','a county on England’s south coast','a county in the Arctic Circle','a village inside a greenhouse','a county on England’s south coast','该郡位于英格兰南部沿海区域。')]});
D('hamster',{etymology:E('Hamster came into English from German Hamster, borrowed from a Slavic word related to Russian khomyak. It names a small burrowing rodent that stores food in cheek pouches.','hamster'),contexts:[C('hamster.s1','宠物照料','The hamster pushed sunflower seeds into its cheek pouches and carried them to a quiet corner of the enclosure for later.','仓鼠把葵花籽塞进颊囊，带到笼舍安静的角落留待以后食用。','The hamster pushed sunflower seeds into its cheek pouches / and carried them / to a quiet corner / of the enclosure for later.','hamster 指会用颊囊储存食物的小型啮齿动物。','颊囊储食是仓鼠的典型特征。')],mistakes:[M('The hamster stored its food in external feathers and nested in a tree canopy like a bird.','The hamster stored its food in cheek pouches and nested in a burrow.','仓鼠是穴居啮齿动物，没有鸟类羽毛。')],quiz:[Q('hamster',1,1,'A hamster is a small?','burrowing rodent','marine shark','village','burrowing rodent','hamster 是小型穴居啮齿动物。'),Q('hamster',2,1,'A hamster’s cheek pouches help it?','carry and store food','hear distant sounds','break open glassware','carry and store food','颊囊用于暂存食物。'),Q('hamster',3,1,'Where might a hamster make its home?','in a burrow','on a piano hammer','inside a handbag only','in a burrow','仓鼠会穴居。'),Q('hamster',4,1,'Which pet behavior is typical of a hamster?','packing seeds into its cheek pouches','using a handkerchief to wave','making a nest from steel','packing seeds into its cheek pouches','颊囊储粮是典型行为。')]});
D('hand',{etymology:E('Hand comes from Old English hand, from a Germanic root. Besides the body part, it can mean a clock pointer, a worker, help, or the act of passing something to someone.','hand'),contexts:[C('hand.s4','求助协作','When the shelving unit began to tilt, Mina asked a neighbour for a hand before the heavy books could fall.','书架开始倾斜时，米娜赶紧请邻居帮忙，以免沉重的书掉下来。','When the shelving unit began to tilt / Mina asked a neighbour for a hand / before the heavy books / could fall.','for a hand 是固定搭配，hand 在此表示帮助。','她请求邻居协助扶稳书架，符合 s4。')],mistakes:[M('Mina asked her neighbour for a hand, meaning she wanted only to borrow a clock pointer and receive no help.','Mina asked her neighbour for help in steadying the shelving unit.','语境中的 ask for a hand 表示求助，不是借钟表指针。')],quiz:[Q('hand',1,1,'Your hand is the part of the body at the end of your?','arm','leg','neck','arm','s1 指手臂末端的手。'),Q('hand',2,2,'The minute hand on a clock is?','a pointer showing minutes','a clock repairer','a small basket','a pointer showing minutes','s2 指钟表上的指针。'),Q('hand',3,3,'A farm hand is?','a worker','a hand gesture','a type of orange','a worker','s3 指工人、尤指体力劳动者。'),Q('hand',4,4,'If you give someone a hand, you give them?','help','a clock face','a village','help','s4 表示援助。')]});
D('hand in',{etymology:E('Hand in is a phrasal verb formed from hand “pass” and the particle in. It means submit or give something to an authority, such as homework to a teacher.','hand in'),contexts:[C('hand in.s1','课程作业','Students must hand in the lab report by noon on Friday, attaching the signed safety checklist to the final page.','学生必须在周五中午前交实验报告，并把签过字的安全清单附在最后一页。','Students must hand in the lab report / by noon on Friday / attaching the signed safety checklist / to the final page.','hand in 是“上交、提交”，后接要交的作业或文件。','报告交给课程负责人，符合该短语义。')],mistakes:[M('The class was told to hand in the report by keeping it at home and never giving it to the teacher.','The class was told to keep a copy and hand in the report to the teacher.','留在家中且不交给老师与 hand in 的要求相反。')],quiz:[Q('hand in',1,1,'To hand in homework is to?','submit it to the teacher','take it back from the teacher','write it on your hand','submit it to the teacher','hand in 表示提交作业。'),Q('hand in',2,1,'A student should hand in a report?','by delivering it to the instructor','by deleting every copy','by handing it to a stranger in the street','by delivering it to the instructor','作业交给负责教师才是提交。'),Q('hand in',3,1,'Which object can you hand in at a library?','an overdue form or requested document','a clock’s minute hand','a pet hamster','an overdue form or requested document','文件可交给图书馆工作人员。'),Q('hand in',4,1,'In a deadline notice, “hand in by Friday” means?','submit no later than Friday','begin reading on Friday','take the paper away on Friday','submit no later than Friday','by Friday 表示最迟在周五提交。')]});
D('hand out',{etymology:E('Hand out combines hand “pass” with out, suggesting distributing items from oneself to others. It means give things to a number of people.','hand out'),contexts:[C('hand out.s1','课堂分发','Before the workshop began, the instructor handed out printed checklists so each participant could mark the equipment they had inspected.','工作坊开始前，讲师给每位参与者发了一份纸质清单，让大家勾选已检查的设备。','Before the workshop began / the instructor handed out printed checklists / so each participant / could mark the equipment they had inspected.','hand out 是分发，把多份物品给多人。','清单逐一发给参与者，符合该短语义。')],mistakes:[M('The instructor handed out the checklists by collecting every copy from participants and locking them away.','The instructor collected the checklists from participants and locked them away.','收回并锁起清单是 collect，不是 hand out。')],quiz:[Q('hand out',1,1,'To hand out leaflets is to?','distribute them to people','collect them from the floor','hide them in a cabinet','distribute them to people','hand out 表示分发。'),Q('hand out',2,1,'A teacher may hand out?','a worksheet to every student','one clock hand to a repair shop','a handbag to a burglar','a worksheet to every student','逐份发给学生就是分发。'),Q('hand out',3,1,'Which verb has the opposite direction from hand out?','collect','distribute','give','collect','collect 表示收集，与发出相反。'),Q('hand out',4,1,'The volunteers handed out water during the race. They?','gave bottles to runners','took bottles away from runners','made the runners build a village','gave bottles to runners','志愿者把水分给参赛者。')]});
D('hand over',{etymology:E('Hand over combines hand “pass” with over, suggesting transfer from one holder or authority to another. It means give possession or control to someone else.','hand over'),contexts:[C('hand over.s1','岗位交接','At the end of her shift, the nurse handed over the patient notes and explained which test results still needed follow-up.','交班时，护士移交了病历记录，并说明哪些检查结果仍需跟进。','At the end of her shift / the nurse handed over the patient notes / and explained / which test results still needed follow-up.','hand over 指把物品、职责或控制权移交给另一方。','病历和未完成事项由下一班接手，符合义项。')],mistakes:[M('The nurse handed over the patient notes by keeping them and refusing to let the next shift see them.','The nurse kept the patient notes and refused to hand them over to the next shift.','扣留记录而非交给下一班，与 hand over 相反。')],quiz:[Q('hand over',1,1,'To hand over a key is to?','give it to another person','hide it from everyone','copy it into a handbook','give it to another person','hand over 表示交出、移交。'),Q('hand over',2,1,'A manager may hand over control when?','a successor takes responsibility','the manager refuses to leave','a clock changes its minute hand','a successor takes responsibility','权力交给继任者就是移交控制权。'),Q('hand over',3,1,'Which item might be handed over at shift change?','unfinished case notes','a village’s population','a hamster’s cheek pouch','unfinished case notes','工作交接时常移交记录和待办事项。'),Q('hand over',4,1,'“The suspect handed over the keys” means the suspect?','gave the keys to someone else','borrowed the keys and hid them','broke the keys with a hammer','gave the keys to someone else','hand over 说明把钥匙交给另一方。')]});
D('hand-operated',{etymology:E('Hand-operated combines hand with operated, the past participle of operate. It describes equipment powered or controlled directly by a person’s hand rather than by an engine or automatic system.','hand-operated'),contexts:[C('hand-operated.s1','厨房工具','The hand-operated grinder lets the cook control the speed by turning a crank instead of plugging in a motor.','这台手摇磨机让厨师通过转动曲柄控制速度，而不必插电使用马达。','The hand-operated grinder / lets the cook control the speed / by turning a crank / instead of plugging in a motor.','hand-operated 修饰 grinder，表示由人手操作而非电动。','转动曲柄提供动力，符合手动操作义。')],mistakes:[M('The hand-operated pump ran entirely on an electric motor and had no handle, crank, or manual control.','The motor-operated pump ran on electricity and had no manual crank.','完全由电机驱动、不能手动操作的泵不是 hand-operated。')],quiz:[Q('hand-operated',1,1,'A hand-operated machine is powered or controlled by?','a person using their hand','a built-in engine only','a remote glacier','a person using their hand','该复合形容词表示用手操作。'),Q('hand-operated',2,1,'Which device is hand-operated?','a grinder turned by a crank','an automatic pump with no controls','a self-driving car','a grinder turned by a crank','手摇曲柄由人力驱动。'),Q('hand-operated',3,1,'A hand-operated tool differs from an electric one because it?','does not depend on an electric motor','cannot be held','must be made of glass','does not depend on an electric motor','手动工具由人力而非电机供能。'),Q('hand-operated',4,1,'The hyphenated compound means?','operated by hand','operated by a hamster','made entirely of hands','operated by hand','hand + operated 说明操作方式。','word-formation')]});
D('handbag',{etymology:E('Handbag combines hand with bag. The compound has been used for a small bag carried by hand, especially one used to hold personal belongings.','handbag'),contexts:[C('handbag.s1','出行整理','Rosa put her passport, medication, and wallet in her handbag before leaving for the airport, then kept it under the seat.','罗莎去机场前把护照、药品和钱包放进手提包，随后将包放在座位下方。','Rosa put her passport, medication, and wallet in her handbag / before leaving for the airport / then kept it / under the seat.','handbag 指随身手提的小包。','护照、药物和钱包是常放在手提包中的随身物品。')],mistakes:[M('She stored her handbag in a warehouse because it was a large freight container carried by ship.','She stored her luggage in a warehouse because it was too large to carry as a handbag.','手提包是随身小包，不是大型货运集装箱。')],quiz:[Q('handbag',1,1,'A handbag is a small bag usually?','carried by hand or on the arm','worn as a hard hat','used to hit nails','carried by hand or on the arm','handbag 是随身携带的小包。'),Q('handbag',2,1,'What might someone keep in a handbag?','a wallet and keys','a bridge girder','a whole washing machine','a wallet and keys','钱包和钥匙是常见随身物品。'),Q('handbag',3,1,'A handbag is most useful when?','carrying personal items while travelling','lifting a car engine','sheltering a village','carrying personal items while travelling','手提包用于携带个人物品。'),Q('handbag',4,1,'The compound handbag refers to?','a bag for carrying personal belongings','a device controlled by a hand crank','a small village','a bag for carrying personal belongings','词义是手提包。','word-formation')]});
D('handball',{etymology:E('Handball combines hand and ball. It names a team sport played by throwing and catching a ball, a court game struck by hand, and in football the offence of touching the ball with the hand or arm.','handball'),contexts:[C('handball.s2','足球比赛','The referee awarded a free kick after the defender committed handball by stopping the cross with an outstretched arm.','防守队员伸手臂挡住传中球后犯了手球，裁判因此判给对方任意球。','The referee awarded a free kick / after the defender committed handball / by stopping the cross / with an outstretched arm.','handball 在此指足球中用手或手臂触球的犯规。','故意以伸出的手臂挡球对应 s2。')],mistakes:[M('The referee called handball when the player headed the ball without touching it with an arm or hand.','The referee called a handball only after the player touched the ball with an arm.','没有手臂或手触球不构成这里的足球手球犯规。')],quiz:[Q('handball',1,1,'In the team sport, handball players mainly?','throw and catch a ball','hit a ball with a golf club','throw a hammer at a goal','throw and catch a ball','s1 指投掷接球的团队运动。'),Q('handball',2,2,'In football, handball is an offence involving?','touching the ball with the hand or arm','heading the ball','kicking the ball with a foot','touching the ball with the hand or arm','s2 指足球手球犯规。'),Q('handball',3,1,'A handball court game may involve?','striking a ball with the hand','sewing a handbag','feeding a hamster','striking a ball with the hand','另一种手球运动用手击球。'),Q('handball',4,2,'A defender blocks a cross with an arm. The referee may call?','handball','handcraft','a hamper','handball','手臂挡球可能构成足球手球犯规。')]});
D('handbook',{etymology:E('Handbook combines hand and book and has been used since the sixteenth century for a compact manual or guide. It can also refer to a guidebook for travellers.','handbook'),contexts:[C('handbook.s2','旅行规划','Before renting a car, the family checked a travel handbook for ferry schedules, road rules, and the opening hours of small museums.','租车前，一家人查阅旅行指南，了解渡船时刻、道路规则和小型博物馆的开放时间。','Before renting a car / the family checked a travel handbook / for ferry schedules, road rules / and the opening hours of small museums.','handbook 在此指旅行者使用的指南书。','查询交通与景点信息，符合 s2。')],mistakes:[M('They used the travel handbook to bake bread because it contained only recipes and no travel information.','They used a cookbook to bake bread because the travel handbook covered routes and local information.','只含食谱的书是 cookbook，不是旅行指南。')],quiz:[Q('handbook',1,1,'A safety handbook usually contains?','instructions and useful information','a person’s hand','a bag of dirty clothes','instructions and useful information','s1 指说明或资料手册。'),Q('handbook',2,2,'A traveller may consult a handbook for?','routes, rules, and local sights','the temperature inside a hamster’s burrow','a piano’s striking mechanism','routes, rules, and local sights','s2 是旅行指南。'),Q('handbook',3,1,'Which item is most likely a handbook?','a compact guide to workplace procedures','a handbag without pages','a ball used in court sports','a compact guide to workplace procedures','手册集中提供实用信息。'),Q('handbook',4,1,'The compound handbook originally suggests?','a book small enough to hold in the hand','a book written only by hand','a collection of gloves','a book small enough to hold in the hand','该复合词指便于手持的指南或手册。','word-formation')]});
D('handcraft',{etymology:E('Handcraft combines hand and craft. As a verb it means make something by hand using skill; the related noun handicraft names the skill or product.','handcraft'),contexts:[C('handcraft.s1','陶艺体验','Participants handcraft small bowls from local clay, shaping each wall with their fingers before smoothing the rim with a damp sponge.','参与者用当地黏土手工制作小碗，用手指塑出碗壁，再用湿海绵抹平边缘。','Participants handcraft small bowls from local clay / shaping each wall with their fingers / before smoothing the rim / with a damp sponge.','handcraft 在此作动词，表示凭手艺手工制作。','用手塑形并修整陶碗体现手工制作。')],mistakes:[M('The factory handcrafts each bowl by fully automating every step and preventing workers from touching the clay.','The factory mass-produces the bowls by automating every step.','全流程自动化批量生产与手工制作相反。')],quiz:[Q('handcraft',1,1,'To handcraft a bowl is to?','make it by hand with skill','buy it ready-made','make it only by machine','make it by hand with skill','handcraft 作动词表示手工制作。'),Q('handcraft',2,1,'Which activity is handcrafting?','carving a wooden spoon by hand','ordering a spoon from a factory','reading a travel handbook','carving a wooden spoon by hand','手工雕刻木勺符合该词。'),Q('handcraft',3,1,'A handcraft item is usually?','made through manual skill','automatically assembled with no handwork','a type of official document','made through manual skill','该动词强调手工技艺。'),Q('handcraft',4,1,'The compound handcraft links manual work with?','a skilled craft','a medical examination','a county government','a skilled craft','handcraft 由 hand 与 craft 组合。','word-formation')]});
D('handedness',{etymology:E('Handedness is formed from handed plus -ness. It names a person’s preference for using the right or left hand, commonly called right-handedness or left-handedness.','handedness'),contexts:[C('handedness.s1','动作研究','The researcher recorded each child’s handedness by noting which hand they naturally chose for drawing, cutting, and throwing.','研究人员通过观察每个孩子画画、剪纸和投掷时自然选用哪只手，记录其惯用手倾向。','The researcher recorded each child’s handedness / by noting which hand / they naturally chose / for drawing, cutting, and throwing.','handedness 指惯用左手还是右手的倾向。','多项动作中观察偏好手，符合定义。')],mistakes:[M('Her handedness was left-handed even though she performed every task equally with both hands and showed no preference.','Her handedness was mixed because she showed no consistent preference for either hand.','没有任何惯用手偏好时，不能断言其偏左手。')],quiz:[Q('handedness',1,1,'Handedness describes whether someone prefers?','the right or left hand','a handbag or a backpack','one village or another','the right or left hand','handedness 指惯用手偏好。'),Q('handedness',2,1,'A researcher might test handedness by observing which hand a child uses to?','draw or throw','hear a telephone','wear a hard hat','draw or throw','精细动作和投掷可用于观察惯用手。'),Q('handedness',3,1,'A left-handed person usually prefers the?','left hand for many tasks','right foot for every task','handbook over a notebook','left hand for many tasks','左撇子多倾向使用左手。'),Q('handedness',4,1,'The suffix -ness turns handed into a noun naming?','a state or quality','a tool for hitting nails','a small village','a state or quality','-ness 构成表示状态、性质的名词。','word-formation')]});
D('handful',{etymology:E('Handful is formed from hand plus -ful, first meaning as much as a hand can hold. It also means a small number and, informally, a person or task that is difficult to manage.','handful'),contexts:[C('handful.s3','育儿日常','The puppy was a handful during the long train ride, tugging at the lead and barking whenever another dog walked past.','长途火车旅行中，这只小狗很难管；每当有别的狗经过，它就拉牵引绳并吠叫。','The puppy was a handful during the long train ride / tugging at the lead / and barking whenever / another dog walked past.','a handful 在此比喻难以管束的人或动物。','小狗一路难以控制，符合 s3。')],mistakes:[M('The puppy was a handful because it sat quietly, followed every command, and caused no difficulty at all.','The puppy was easy to manage because it sat quietly and followed every command.','安静听话、毫无麻烦不能称为 a handful。')],quiz:[Q('handful',1,1,'A handful of nuts is?','as much as one hand can hold','a small tool for cutting','a group of several villages','as much as one hand can hold','s1 指一把的量。'),Q('handful',2,2,'A handful of students means?','a small number of students','every student in the country','one handful of soil','a small number of students','s2 表示少数几个。'),Q('handful',3,3,'A lively puppy that is hard to control can be?','a handful','a handbook','a handout','a handful','s3 指棘手、难管的人或事。'),Q('handful',4,1,'Which amount is literally a handful?','seeds held in a cupped palm','a full truckload of gravel','one drop of water','seeds held in a cupped palm','字面义是一只手能握住的量。')]});
D('handgun',{etymology:E('Handgun combines hand and gun, naming a small firearm designed to be held and fired in one hand.','handgun'),contexts:[C('handgun.s1','安全法规','The new law requires secure storage for every handgun, with ammunition kept separately and the firearm locked away from children.','新法规要求每支手枪安全存放，弹药须分开保管，并把枪锁好以免儿童接触。','The new law requires secure storage for every handgun / with ammunition kept separately / and the firearm locked away / from children.','handgun 指可单手持用的小型枪械。','法规特别要求对手枪和弹药进行安全存放。')],mistakes:[M('The officer described the handgun as a shoulder-fired cannon too large for anyone to hold in one hand.','The officer described the handgun as a small firearm designed to be held in one hand.','大型肩射火炮与手枪的尺寸和持握方式不符。')],quiz:[Q('handgun',1,1,'A handgun is a small firearm held?','in one hand','on the shoulder by a crew','inside a handbag as a toy','in one hand','handgun 是单手持用的小型枪械。'),Q('handgun',2,1,'A handgun should be stored?','securely and away from children','loaded on an open table','inside a hamster’s cage','securely and away from children','枪械应安全上锁并避免儿童接触。'),Q('handgun',3,1,'Which object is a handgun?','a pistol','a bridge girder','a handkerchief','a pistol','手枪属于 handgun。'),Q('handgun',4,1,'The compound handgun emphasizes that the firearm is?','small enough to be held by hand','made entirely from hands','used only to hammer nails','small enough to be held by hand','复合词突出其手持式特点。','word-formation')]});

D('handicap',{etymology:E('Handicap was shortened from the phrase “hand in cap,” an old method of settling exchanges by placing contributions in a cap. It now means an obstacle, a disability in older usage, a sporting allowance, or the act of putting someone at a disadvantage.','handicap'),contexts:[C('handicap.s3','高尔夫比赛','The club gave the stronger golfer a handicap of six strokes so the newcomer could compete on more equal terms.','俱乐部给实力较强的高尔夫球手让了六杆，使新手能在更平等的条件下参赛。','The club gave the stronger golfer a handicap / of six strokes / so the newcomer could compete / on more equal terms.','handicap 在此指为平衡比赛机会而给强手设置的让步。','给强手加杆数缩小双方差距，符合 s3。')],mistakes:[M('The tournament gave the beginner a handicap by adding extra strokes to the stronger player to make the contest less equal.','The tournament gave the stronger player a handicap to make the contest more equal.','让分是为平衡实力差距，不是故意扩大不平等。')],quiz:[Q('handicap',1,1,'A lack of transport can be a handicap because it?','makes success more difficult','guarantees an easy victory','is a piece of sporting equipment','makes success more difficult','s1 指妨碍成功的不利条件。'),Q('handicap',2,2,'In older usage, handicap could refer to?','a physical or mental disability','a helpful prize','a type of hand tool','a physical or mental disability','s2 为较旧用法，指残疾或缺陷。'),Q('handicap',3,3,'A golf handicap is intended to?','make players of different ability compete more fairly','give every strong player an automatic win','exclude beginners from the match','make players of different ability compete more fairly','s3 是为均衡竞技机会设置的让步。'),Q('handicap',4,4,'To handicap a team is to?','put it at a disadvantage','hand it a trophy','teach it a handcraft','put it at a disadvantage','s4 作动词表示使处于不利地位。')]});
D('handicapped',{etymology:E('Handicapped is formed from handicap plus -ed and historically meant having a disability. The term is now often avoided for people; disabled or a specific description is generally preferred.','handicapped'),contexts:[C('handicapped.s1','无障碍设施','The archived sign used the older word handicapped, while the updated guide refers to disabled visitors and lists accessible entrances.','旧档案标牌使用了较旧的 handicapped 一词，而新版指南改称残障访客并列出无障碍入口。','The archived sign used the older word handicapped / while the updated guide refers to disabled visitors / and lists / accessible entrances.','handicapped 是指有残疾的旧式表达；指人时当代用语常偏好 disabled 或具体描述。','句子明确比较旧标牌与新版的用词选择。')],mistakes:[M('The guide called every visitor handicapped solely because they used a handbag and listed no accessibility information.','The guide described visitors with disabilities accurately and provided accessibility information.','使用手提包与残疾无关，不能据此把访客标为 handicapped。')],quiz:[Q('handicapped',1,1,'In older English usage, handicapped means?','having a disability','carrying a handbag','being a village resident','having a disability','词典义为有残疾，但该用法现常被避免。'),Q('handicapped',2,1,'When writing about a person’s disability today, a guide often prefers?','disabled or a specific description','a label based on unrelated possessions','an insulting nickname','disabled or a specific description','对人描述时通常更偏好 disabled 或具体说明。'),Q('handicapped',3,1,'Why might an updated sign replace handicapped with disabled?','the older label is now often avoided','the new word means “able to use a handbag”','the two words refer to different counties','the older label is now often avoided','该旧词用于人时越来越少见。'),Q('handicapped',4,1,'A respectful access guide should focus on?','the person and relevant accessibility needs','assuming disability from a person’s appearance alone','using the oldest label in every context','the person and relevant accessibility needs','用语应尊重当事人并说明实际无障碍信息。')]});
D('handicraft',{etymology:E('Handicraft combines handi-, an older form related to hand, with craft. It names the skill of making things by hand and also objects produced through that skill.','handicraft'),contexts:[C('handicraft.s2','手作市集','At the weekend market, the potter displayed each handmade handicraft with a card describing the clay and firing technique.','周末市集上，陶艺家展示每件手工艺品，并附卡片介绍所用黏土和烧制技法。','At the weekend market / the potter displayed each handmade handicraft / with a card / describing the clay and firing technique.','handicraft 在此指手工制作出来的物品。','陶器作为手工制作的成品，符合 s2。')],mistakes:[M('The factory-made plastic cup was sold as a traditional handicraft even though no one shaped it by hand.','The factory-made plastic cup was sold as a mass-produced item rather than a handicraft.','完全机器批量生产的杯子不符合手工艺品义。')],quiz:[Q('handicraft',1,1,'Handicraft can mean the skill of?','making things by hand','operating a phone handset','governing a county','making things by hand','s1 指手工制作技艺。'),Q('handicraft',2,2,'A carved wooden bowl sold at a craft fair is a?','handicraft','handgun','handout','handicraft','s2 可指手工制作的物件。'),Q('handicraft',3,1,'Which activity develops handicraft skills?','weaving a basket by hand','ordering a mass-produced basket','reading a hard hat label','weaving a basket by hand','手工编织体现 handicraft 技艺。'),Q('handicraft',4,2,'A decorative object made by an artisan may be called?','a handicraft','a hamper verb','a handset','a handicraft','手工艺品可以称为 handicraft。')]});
D('handiwork',{etymology:E('Handiwork combines handi-, a form related to hand, with work. It means things made by someone’s own hands or the visible result of their skill.','handiwork'),contexts:[C('handiwork.s1','修复成果','The restored chair was her handiwork: she had replaced the loose joints, carved a matching rail, and refinished the wood herself.','修复后的椅子是她亲手完成的作品：她更换了松动的榫头，雕出相配的横档，还亲自重新上漆。','The restored chair was her handiwork / she had replaced the loose joints / carved a matching rail / and refinished the wood herself.','handiwork 指某人亲手制作或修复的成果。','句子列出她亲自完成的多项木工工作。')],mistakes:[M('The chair was his handiwork even though he had never touched it and an automated line made every part.','The chair was mass-produced by an automated line rather than being his handiwork.','无人手工参与、完全自动生产的物品不能称为某人的 handiwork。')],quiz:[Q('handiwork',1,1,'Your handiwork is?','work or objects you made yourself','a basket for dirty laundry','a person who lives off others','work or objects you made yourself','handiwork 指亲手做出的成果。'),Q('handiwork',2,1,'Which is most clearly a craftsperson’s handiwork?','a chair they carved and assembled','a chair bought sealed from a factory','a phone receiver','a chair they carved and assembled','亲手雕刻和组装体现 handiwork。'),Q('handiwork',3,1,'A repaired quilt may be called someone’s handiwork because?','they made or repaired it by hand','it is only a written guide','it is too heavy to lift','they made or repaired it by hand','该词强调个人手工成果。'),Q('handiwork',4,1,'The compound handiwork is closest in meaning to?','work done by hand','work done by a county council','a hand signal','work done by hand','handi- 与 work 组合表示手工成果。','word-formation')]});
D('handkerchief',{etymology:E('Handkerchief combines hand with kerchief, from Old French couvrechief “head covering.” It came to mean a small piece of cloth or paper carried for wiping the nose or face.','handkerchief'),contexts:[C('handkerchief.s1','日常携带','When the child’s nose began to run in the cold air, her father offered a clean cloth handkerchief from his coat pocket.','孩子在冷空气中开始流鼻涕时，父亲从外套口袋里拿出一块干净的布手帕递给她。','When the child’s nose began to run / in the cold air / her father offered / a clean cloth handkerchief from his coat pocket.','handkerchief 是随身携带、用于擦鼻子或脸的小块布。','布手帕从口袋取出并用来擦鼻子，符合定义。')],mistakes:[M('He used the handkerchief to hammer a nail into the wall because the cloth was a metal tool.','He used a hammer to drive the nail and kept the handkerchief for wiping his face.','手帕是布或纸制品，不是敲钉工具。')],quiz:[Q('handkerchief',1,1,'A handkerchief is a small piece of cloth or paper used to?','wipe the nose or face','drive nails into wood','store a whole hamper','wipe the nose or face','手帕常用于擦鼻子或脸。'),Q('handkerchief',2,1,'Someone might carry a handkerchief in?','a coat pocket','a piano hammer','a county boundary','a coat pocket','手帕通常便于随身携带。'),Q('handkerchief',3,1,'Which material can a handkerchief be made from?','cloth or paper','only steel','only glass','cloth or paper','手帕可以是布制或纸制。'),Q('handkerchief',4,1,'The historical kerchief was a kind of?','covering cloth','small firearm','orange cultivar','covering cloth','kerchief 原指覆盖头部的布。','word-formation')]});
D('handle',{etymology:E('Handle is formed from hand plus the verbal suffix -le and is recorded in Old English. It can mean deal with, hold or move by hand, operate, a part held in the hand, or leverage against someone.','handle'),contexts:[C('handle.s5','谈判沟通','The journalist’s questions gave the mayor’s opponents a handle they could use to challenge the budget figures in public.','记者的问题给了市长的反对者一个可乘之机，他们可以据此公开质疑预算数字。','The journalist’s questions gave the mayor’s opponents a handle / they could use / to challenge the budget figures / in public.','a handle 在此比喻可供利用的把柄或机会。','问题提供了反对者据以质疑的材料，符合 s5。')],mistakes:[M('The interview gave the mayor’s opponents no handle at all, yet they used its clear evidence as leverage against the budget.','The interview gave the mayor’s opponents a handle they used as leverage against the budget.','若对方确实利用证据施压，就不能说没有把柄或机会。')],quiz:[Q('handle',1,1,'To handle a complaint is to?','deal with it','hang it on a wall','turn it into a handbag','deal with it','s1 表示处理问题。'),Q('handle',2,2,'To handle a fragile glass is to?','hold or move it carefully','write a complaint about it','govern the shop','hold or move it carefully','s2 指用手拿或搬动。'),Q('handle',3,4,'A suitcase handle is?','the part designed to be held','the person who carries it','the written travel guide','the part designed to be held','s4 指供握持的部件。'),Q('handle',4,5,'A damaging email can give opponents a handle to?','use against someone','repair a vehicle','hold a clock pointer','use against someone','s5 指可利用的把柄或机会。')]});
D('handling',{etymology:E('Handling is formed from handle plus -ing. It can mean the way a person manages people, goods, or a problem, and in vehicle contexts it describes how a vehicle responds to steering.','handling'),contexts:[C('handling.s2','汽车评测','The review praised the hatchback’s handling on wet bends, noting that the steering stayed predictable when the road surface changed.','评测称赞这款两厢车在湿滑弯道上的操控表现，指出路面状况变化时转向仍很稳定。','The review praised the hatchback’s handling on wet bends / noting that the steering stayed predictable / when the road surface / changed.','handling 在此指车辆对驾驶者操作的响应和操控性。','弯道转向稳定性对应汽车操控义。')],mistakes:[M('The car’s handling was excellent because it ignored the steering input and continued straight through every turn.','The car handled poorly because it ignored the steering input and continued straight through every turn.','不响应转向说明操控性差，不是 excellent handling。')],quiz:[Q('handling',1,1,'The handling of a difficult complaint means?','the way it is managed','the shape of a phone receiver','the number of workers','the way it is managed','s1 指管理或处理的方式。'),Q('handling',2,2,'A car with good handling?','responds predictably to steering','cannot turn when the wheel moves','is always made by hand','responds predictably to steering','s2 指车辆对驾驶操作的响应。'),Q('handling',3,1,'Careful handling of fragile goods helps prevent?','damage during transport','the goods becoming a village','their turning into a handset','damage during transport','货物处理方式影响是否损坏。'),Q('handling',4,2,'A test of a vehicle’s handling may examine?','how it behaves through bends','how many handkerchiefs it can hold','how its passengers write','how it behaves through bends','弯道表现是车辆操控性的指标。')]});
D('handmade',{etymology:E('Handmade combines hand with the past participle made. It describes something produced by a person’s hands rather than by machine manufacture.','handmade'),contexts:[C('handmade.s1','手工礼物','Each handmade notebook had a different marbled cover because the bookbinder poured and combed the coloured inks by hand.','每本手工笔记本的云纹封面都不同，因为装订师亲手倾倒并梳理了彩色墨水。','Each handmade notebook had a different marbled cover / because the bookbinder poured / and combed the coloured inks / by hand.','handmade 表示由人手制作，而非机器批量制造。','封面由装订师亲手制作，体现手工属性。')],mistakes:[M('The handmade notebooks came off a fully automated line with no manual steps or individual work.','The machine-made notebooks came off a fully automated line.','全自动流水线生产的笔记本应称 machine-made。')],quiz:[Q('handmade',1,1,'A handmade object is?','made by a person’s hands','made only by an automatic machine','a hand-shaped basket used for clothes','made by a person’s hands','handmade 表示手工制作。'),Q('handmade',2,1,'A handmade notebook may have?','individual details added by its maker','identical machine-only features in every copy','a motor inside its cover','individual details added by its maker','手工制作常留下个体差异。'),Q('handmade',3,1,'Which product is handmade?','a bowl shaped and painted by an artisan','a mass-produced bowl from an automated line','a printed instruction sheet','a bowl shaped and painted by an artisan','工匠手工塑形和绘制的碗是 handmade。'),Q('handmade',4,1,'Handmade is the opposite of?','machine-made','hand-operated','handwritten','machine-made','该词强调手工，而非机器生产。','word-formation')]});
D('handout',{etymology:E('Handout is formed from hand out, a phrasal verb meaning distribute. It can name printed material given to an audience, free aid, or a promotional leaflet handed to people.','handout'),contexts:[C('handout.s2','社区援助','After the storm, volunteers prepared a handout of blankets and bottled water for households whose homes had lost power.','暴风雨过后，志愿者为停电的家庭准备了毯子和瓶装水等救济物资。','After the storm / volunteers prepared a handout of blankets and bottled water / for households / whose homes had lost power.','handout 在此指免费提供给有需要者的救济品。','毯子和水免费发给受灾家庭，符合 s2。')],mistakes:[M('The storm victims received a handout only after paying the full retail price for every blanket and bottle.','The storm victims received supplies they had paid for rather than a free handout.','付足零售价购买的物品不是免费救济品。')],quiz:[Q('handout',1,1,'A lecturer’s handout is?','printed material given to listeners','a phone part held to the ear','a type of government','printed material given to listeners','s1 指课堂或讲座上发放的资料。'),Q('handout',2,2,'Food given free to families in need is a?','handout','handwriting','handball','handout','s2 指免费救济品。'),Q('handout',3,3,'A shop may hand out a promotional handout to?','advertise a product','regulate an engine','train a hamster','advertise a product','s3 是公开散发的宣传品。'),Q('handout',4,2,'A relief handout is different from a purchase because it is?','given free to people in need','always a printed guide','paid for at full price','given free to people in need','救济品通常免费发放。')]});
D('hands-on',{etymology:E('Hands-on combines hands with on and is used adjectivally for direct practical involvement or learning by doing.','hands-on'),contexts:[C('hands-on.s1','实操培训','The safety course included hands-on practice with the fire extinguisher, allowing each trainee to aim, squeeze, and sweep under supervision.','安全课程包含灭火器实操训练，每位学员都在监督下练习瞄准、按压和扫射。','The safety course included hands-on practice with the fire extinguisher / allowing each trainee / to aim, squeeze, and sweep / under supervision.','hands-on 修饰 practice，指亲自动手参与的实践活动。','学员实际操作灭火器，而非只听讲解。')],mistakes:[M('The course was described as hands-on even though trainees only watched a video and never touched any equipment.','The course was video-based rather than hands-on because trainees never practised with equipment.','只观看、不动手操作不符合实践参与义。')],quiz:[Q('hands-on',1,1,'Hands-on learning happens mainly by?','doing practical tasks yourself','reading a list without trying anything','watching from another room','doing practical tasks yourself','hands-on 指亲自实践、动手学习。'),Q('hands-on',2,1,'A hands-on workshop may ask learners to?','assemble a simple device','memorize a description only','avoid all materials','assemble a simple device','实际组装体现动手参与。'),Q('hands-on',3,1,'Which training is hands-on?','trainees practise using the equipment','trainees only hear a lecture','trainees receive no instruction or activity','trainees practise using the equipment','直接练习设备属于 hands-on training。'),Q('hands-on',4,1,'The compound hands-on contrasts with?','theoretical or observational-only learning','manual skill','practical involvement','theoretical or observational-only learning','该词突出亲身参与实践。','word-formation')]});
D('handset',{etymology:E('Handset combines hand and set, a set of telephone components held in the hand. It commonly names the receiver that is lifted to the ear and mouth.','handset'),contexts:[C('handset.s1','电话维修','The technician replaced the cracked handset, then tested the earpiece and microphone before returning the desk phone to the office.','技术员更换了开裂的电话听筒，并在把座机还给办公室前测试了听筒和麦克风。','The technician replaced the cracked handset / then tested the earpiece and microphone / before returning / the desk phone to the office.','handset 指电话上拿在手里、贴近耳朵和嘴部的部件。','该部件包含听筒和麦克风并可拿起使用。')],mistakes:[M('She held the handset to her ear, but the word referred to the entire building’s telephone wiring rather than the receiver.','She held the handset to her ear; it was the phone’s receiver.','贴耳通话的部件是听筒，不是整栋楼的线路。')],quiz:[Q('handset',1,1,'A phone handset is held?','to the ear and mouth','around the waist','under a desk as a foot','to the ear and mouth','handset 是手持电话听筒。'),Q('handset',2,1,'Which part is usually included in a telephone handset?','earpiece and microphone','a bridge girder','a laundry basket','earpiece and microphone','听筒部件通常含听筒和麦克风。'),Q('handset',3,1,'A cracked handset would most affect?','speaking and listening on the phone','the phone’s wall outlet only','the caller’s handwriting','speaking and listening on the phone','听筒损坏会影响通话收听和说话。'),Q('handset',4,1,'Why is a phone receiver called a handset?','it is a set of parts held in the hand','it is always operated by a hamster','it is a written handout','it is a set of parts held in the hand','该复合词指手持的电话部件。','word-formation')]});
D('handsome',{etymology:E('Handsome is formed from hand plus an older suffix meaning “easy to handle” or “suitable.” Its senses expanded to good-looking, dignified in appearance, generous in amount, and noble in conduct.','handsome'),contexts:[C('handsome.s3','商业报道','The small firm earned a handsome profit after its careful redesign cut waste without lowering the quality of its products.','这家小公司在谨慎改造流程、减少浪费且不降低产品质量后，获得了可观利润。','The small firm earned a handsome profit / after its careful redesign / cut waste / without lowering the quality of its products.','handsome 修饰 profit，表示数量可观、丰厚。','利润显著增加，符合 s3。')],mistakes:[M('The firm earned a handsome profit of only one cent after spending a million dollars, leaving it deeply in debt.','The firm suffered a loss after spending a million dollars to earn only one cent.','一分钱收入相较巨额支出不能称为丰厚利润。')],quiz:[Q('handsome',1,1,'A handsome man is usually?','good-looking','carrying a basket','working as a hand','good-looking','s1 尤指男性英俊、相貌好看。'),Q('handsome',2,2,'A handsome woman in the older sense may look?','attractive in a dignified way','rough and careless','like a phone receiver','attractive in a dignified way','s2 形容女性时可指端庄、健美。'),Q('handsome',3,3,'A handsome reward is?','large or generous','tiny and inadequate','a type of handcraft','large or generous','s3 指可观、丰厚。'),Q('handsome',4,4,'A handsome gesture may be?','noble and generous in spirit','visually unattractive','a way to harm someone','noble and generous in spirit','s4 指行为慷慨高尚。')]});
D('handsomely',{etymology:E('Handsomely is formed from handsome plus -ly. It can mean generously or to a large degree, and can also mean in an attractive or impressive manner.','handsomely'),contexts:[C('handsomely.s1','报酬谈判','The designer was handsomely paid for finishing the urgent project early, receiving a bonus in addition to the agreed fee.','设计师因提前完成紧急项目而获得丰厚报酬，除约定费用外还拿到奖金。','The designer was handsomely paid / for finishing the urgent project early / receiving a bonus / in addition to the agreed fee.','handsomely 在此表示大方、丰厚地。','额外奖金使报酬相当丰厚，符合 s1。')],mistakes:[M('The designer was handsomely paid a single cent for a month of urgent work, with no other compensation.','The designer was poorly paid a single cent for a month of urgent work.','微不足道的报酬不能称为 handsomely paid。')],quiz:[Q('handsomely',1,1,'To be paid handsomely is to be paid?','generously or a large amount','with a neat handwriting style','only in cash','generously or a large amount','s1 表示报酬丰厚。'),Q('handsomely',2,2,'A building decorated handsomely looks?','attractive or impressive','poorly maintained','like a laundry basket','attractive or impressive','s2 表示外观漂亮、令人印象深刻。'),Q('handsomely',3,1,'Which sentence uses handsomely for amount?','The contractor was handsomely rewarded.','The room was handsomely painted blue.','He wrote handsomely with a pencil.','The contractor was handsomely rewarded.','rewarded 强调获得丰厚回报。'),Q('handsomely',4,2,'A handsomely furnished hall is?','furnished in an attractive, impressive way','paid a large salary','left completely empty','furnished in an attractive, impressive way','s2 描写陈设美观大方。')]});
D('handwriting',{etymology:E('Handwriting combines hand and writing. It can refer to the distinctive style of a person’s written letters or to the act and skill of writing by hand.','handwriting'),contexts:[C('handwriting.s1','文稿辨认','The archivist recognized the letter’s handwriting from the tall narrow capitals and the way the writer crossed each lowercase t.','档案管理员从高而窄的大写字母，以及书写者给每个小写 t 加横的方式，认出了信件笔迹。','The archivist recognized the letter’s handwriting / from the tall narrow capitals / and the way the writer crossed / each lowercase t.','handwriting 在此指个人独特的书写字迹风格。','字母形状和落笔习惯构成笔迹特征。')],mistakes:[M('The handwriting was typed by a printer and showed no letter shapes made by a person’s hand.','The printed text was typeset rather than written by hand.','机械印刷文字不是某人手写的笔迹。')],quiz:[Q('handwriting',1,1,'A person’s handwriting is their?','distinctive style of written letters','phone receiver','way of operating a car','distinctive style of written letters','s1 指个人字迹。'),Q('handwriting',2,2,'Handwriting as an activity means?','the act or skill of writing by hand','a spoken conversation','a handball match','the act or skill of writing by hand','s2 指手写这一活动或技能。'),Q('handwriting',3,1,'An archivist may compare handwriting to identify?','who wrote a historical note','which machine made a handset','how a village is governed','who wrote a historical note','笔迹可用于辨认书写者。'),Q('handwriting',4,2,'Writing a sentence with a pen is an example of?','handwriting','handing over','a handout','handwriting','用笔亲手写字是 handwriting。')]});
D('handy',{etymology:E('Handy is formed from hand plus -y. It means useful and convenient, skilled with the hands, or near enough to reach easily.','handy'),contexts:[C('handy.s3','厨房收纳','The spare flashlight is handy because it hangs beside the kitchen door, where anyone can reach it during a power cut.','备用手电筒放在厨房门旁边，很方便；停电时谁都能顺手拿到。','The spare flashlight is handy / because it hangs beside the kitchen door / where anyone can reach it / during a power cut.','handy 在此表示近在手边、容易取用。','手电筒放在门旁可及时拿到，符合 s3。')],mistakes:[M('The flashlight was handy during the outage even though it was locked in a distant storage room no one could reach.','The flashlight was not handy because it was locked in an inaccessible storage room.','无法取到的物品不能说近在手边。')],quiz:[Q('handy',1,1,'A handy tool is?','useful and convenient','impossible to operate','a person who lives off others','useful and convenient','s1 指有用、方便。'),Q('handy',2,2,'Someone handy with tools is?','skilled at making or repairing things','unable to use their hands','always near a telephone','skilled at making or repairing things','s2 指擅长动手修理或制作。'),Q('handy',3,3,'Keep the first-aid kit handy means keep it?','near and easy to reach','inside a locked faraway room','in the hands of a stranger','near and easy to reach','s3 指近便、易于拿取。'),Q('handy',4,1,'A pocket-sized guide can be handy because it is?','easy to use when needed','too large to carry','only a type of handwriting','easy to use when needed','小巧实用，体现 handy 的方便义。')]});
D('hang',{etymology:E('Hang comes from Old English hangian and has several long-established senses: suspend something, execute by hanging, spend idle time, the way something falls, and learn the “hang” or feel of an activity.','hang'),contexts:[C('hang.s5','技能学习','After two practice rounds, the new baker got the hang of shaping the dough and could make even rolls without checking the diagram.','练习两轮后，新面包师掌握了面团塑形的诀窍，不看示意图也能做出均匀的面包卷。','After two practice rounds / the new baker got the hang of shaping the dough / and could make even rolls / without checking the diagram.','get the hang of 表示逐渐掌握某项技能或诀窍。','练习后能独立塑形，说明已经掌握方法。')],mistakes:[M('After weeks of practice, she still had the hang of the task, meaning she had not learned it at all.','After weeks of practice, she still had not got the hang of the task.','have the hang of 表示已掌握；未学会应说 not got the hang of。')],quiz:[Q('hang',1,1,'To hang a picture is to?','fix it up so it is suspended','carry it inside a hamper','write it in a handbook','fix it up so it is suspended','s1 指把东西挂起来。'),Q('hang',2,2,'The verb hang in a historical sentence about an execution means?','kill by suspending with a rope','spend time idly','learn a new skill','kill by suspending with a rope','s2 是绞刑义，语境需严肃明确。'),Q('hang',3,3,'To hang out at a café is to?','spend time there casually','suspend the café from a wall','give everyone a handout','spend time there casually','s3 指闲逛或消磨时间。'),Q('hang',4,5,'If you get the hang of a task, you?','learn how to do it','put it on a wall','refuse to try it','learn how to do it','s5 指掌握诀窍。')]});
D('hanger',{etymology:E('Hanger is formed from hang plus the agent or instrument suffix -er. In ordinary household use it is an object, often shaped like a shoulder, from which clothes are hung.','hanger'),contexts:[C('hanger.s1','衣物收纳','She put the damp coat on a broad wooden hanger so its shoulders would keep their shape while it dried.','她把潮湿的外套挂在宽木衣架上，让衣肩在晾干时保持形状。','She put the damp coat on a broad wooden hanger / so its shoulders would keep their shape / while it dried.','hanger 指挂衣物的衣架。','衣架支撑外套肩部以便晾干，符合定义。')],mistakes:[M('He hung the coat on a hanger, a small basket designed to carry dirty laundry.','He placed the coat on a clothes hanger and put the dirty laundry in a basket.','挂衣架与装脏衣物的篮子用途不同。')],quiz:[Q('hanger',1,1,'A clothes hanger is used to?','hang garments','wash a handset','carry a handful of fruit','hang garments','hanger 指衣架。'),Q('hanger',2,1,'A broad hanger can help a coat?','keep its shoulder shape','become a handout','turn into an orange','keep its shoulder shape','衣架可支撑衣肩不变形。'),Q('hanger',3,1,'Which item belongs in a closet?','a hanger for a jacket','a hammerhead shark','a golf handicap','a hanger for a jacket','衣架常放在衣柜里挂衣物。'),Q('hanger',4,1,'The suffix -er in hanger identifies it as?','a thing that hangs clothes','a county or district','an activity done by hand','a thing that hangs clothes','此处 -er 构成器具名称。','word-formation')]});
D('hanger-on',{etymology:E('Hanger-on is formed from hang on, with the agent suffix -er and the particle on. It informally describes someone who attaches themselves to another person or group for support or advantage.','hanger-on'),contexts:[C('hanger-on.s1','社交圈观察','The singer’s manager dismissed the hanger-on who appeared at every party, borrowed money, and offered no help in return.','歌手的经理赶走了那个总出现在每场派对、借钱却不提供任何帮助的攀附者。','The singer’s manager dismissed the hanger-on / who appeared at every party / borrowed money / and offered no help in return.','hanger-on 指依附他人、靠别人生活或谋利的人。','反复出席、借钱且不回报，体现依附行为。')],mistakes:[M('The hanger-on supported the group independently, paid every shared cost, and never relied on anyone else.','The independent supporter paid the shared costs and did not act as a hanger-on.','自给自足并承担费用的人不符合寄生依附义。')],quiz:[Q('hanger-on',1,1,'A hanger-on is someone who?','depends on others for support or advantage','hangs clothes in a wardrobe','teaches people to handcraft','depends on others for support or advantage','hanger-on 指依附他人者。'),Q('hanger-on',2,1,'Why might a celebrity dismiss a hanger-on?','the person keeps seeking benefits without contributing','the person repairs every broken tool','the person writes a clear handbook','the person keeps seeking benefits without contributing','只索取好处、不作贡献是该词的典型负面含义。'),Q('hanger-on',3,1,'Which person best fits hanger-on?','a guest who follows a group for free meals and favors','a volunteer who organizes the event','a friend who shares all expenses','a guest who follows a group for free meals and favors','跟随群体获取好处符合 hanger-on。'),Q('hanger-on',4,1,'The hyphenated noun usually has a?','critical or disapproving tone','neutral technical meaning for a coat hook','positive meaning for a generous host','critical or disapproving tone','该词通常带贬义。')]});
D('hangout',{etymology:E('Hangout is formed from hang out, a phrasal verb meaning spend time casually. As a noun it is a place that someone or a group visits often.','hangout'),contexts:[C('hangout.s1','社区生活','The old bookshop café became their regular hangout, where the volunteers met after work to plan weekend reading sessions.','旧书店咖啡馆成了他们常去的聚会地点，志愿者们下班后会在那里商量周末读书活动。','The old bookshop café became their regular hangout / where the volunteers met after work / to plan / weekend reading sessions.','hangout 指某人或群体经常去的地方。','志愿者常在此聚会，符合该名词义。')],mistakes:[M('The café was their hangout, though none of them had ever visited it and they met elsewhere every day.','The café was not their hangout because they never visited it.','从未去过的地方不能说是他们常去的 hangout。')],quiz:[Q('hangout',1,1,'A group’s hangout is?','a place they visit often','a type of coat hanger','the act of submitting homework','a place they visit often','hangout 作名词指常去的地点。'),Q('hangout',2,1,'Which could become a student hangout?','a café where friends meet every afternoon','a locked room no one can enter','a faraway bridge girder','a café where friends meet every afternoon','经常聚会的咖啡馆可称 hangout。'),Q('hangout',3,1,'“This park is our usual hangout” means?','we often spend time here','we are building a park','we never come here','we often spend time here','usual 标明这是常去的地方。'),Q('hangout',4,1,'The noun hangout comes from?','the phrasal verb hang out','the word handset','the name Hampshire','the phrasal verb hang out','hangout 由短语动词 hang out 派生。','word-formation')]});
D('hanker',{etymology:E('Hanker is recorded from the seventeenth century, with its earlier origin uncertain. It means want something persistently and is commonly used with for or after.','hanker'),contexts:[C('hanker.s1','旅行愿望','After months of cold rain, Priya began to hanker after a week of dry sunshine and long walks beside the sea.','经历数月阴雨后，普里娅开始渴望一周晴朗的天气，好沿海边长距离散步。','After months of cold rain / Priya began to hanker after a week of dry sunshine / and long walks / beside the sea.','hanker after 表示持续、强烈地渴望某物。','长期阴雨后对晴天的向往体现持久愿望。')],mistakes:[M('He hankered after a quiet afternoon but strongly disliked the idea and made no effort to get one.','He did not hanker after a quiet afternoon because he disliked the idea.','持续渴望与强烈厌恶该想法相互矛盾。')],quiz:[Q('hanker',1,1,'To hanker for something is to?','want it persistently','give it away unwillingly','hang it on a wall','want it persistently','hanker 表示持续渴望。'),Q('hanker',2,1,'Which phrase is common?','hanker after a quiet holiday','hanker across a telephone','hanker beneath a coat','hanker after a quiet holiday','hanker 常与 for 或 after 搭配。','collocation'),Q('hanker',3,1,'Someone who hankers for home?','longs to return home','has already forgotten home','is repairing a handset','longs to return home','hanker for home 表示想家、渴望回家。'),Q('hanker',4,1,'A hankering for a warm meal is?','a persistent desire for one','a tool used to cook one','a refusal to eat it','a persistent desire for one','名词 hankering 表示强烈愿望。')]});

D('haphazard',{etymology:E('Haphazard combines hap, an older word for chance or fortune, with hazard. It means lacking a plan or orderly method and depending on chance.','haphazard'),contexts:[C('haphazard.s1','现场整理','The archive’s haphazard storage left letters, photographs, and maps mixed together in unlabelled boxes, making the collection difficult to search.','档案馆杂乱无章的存放方式把信件、照片和地图混在无标签的箱子里，令馆藏难以检索。','The archive’s haphazard storage / left letters, photographs, and maps mixed together / in unlabelled boxes / making the collection difficult to search.','haphazard 修饰 storage，表示没有计划、次序混乱。','文件无标记混放，符合无规划义。')],mistakes:[M('The haphazard filing system used a carefully numbered index and placed every document in its labeled folder.','The orderly filing system used a numbered index and labeled folders.','条理清楚、精确编号不符合 haphazard。')],quiz:[Q('haphazard',1,1,'A haphazard plan is?','made without a clear order or method','carefully arranged in advance','guaranteed to succeed','made without a clear order or method','haphazard 指无计划、杂乱的。'),Q('haphazard',2,1,'Which archive is organized haphazardly?','one with mixed papers in unlabelled boxes','one with a searchable numbered catalogue','one sorted by date and author','one with mixed papers in unlabelled boxes','无标签混放体现杂乱无章。'),Q('haphazard',3,1,'A haphazard approach relies mainly on?','chance rather than a plan','a precise checklist','a formal schedule','chance rather than a plan','hap 与 chance 相关，形成无计划之义。','word-formation'),Q('haphazard',4,1,'Which result might follow haphazard storage?','items are difficult to locate','each file is found immediately','all materials are perfectly indexed','items are difficult to locate','缺少次序会令资料难以查找。')]});
D('haphazardly',{etymology:E('Haphazardly is formed from haphazard plus -ly. It means in a random, disorganized way, without a consistent plan.','haphazardly'),contexts:[C('haphazardly.s1','城市规划','The new stalls were placed haphazardly along the narrow lane, blocking shop entrances and leaving no clear path for pedestrians.','新摊位杂乱地摆在狭窄巷道上，挡住店铺入口，也没有给行人留下清晰通道。','The new stalls were placed haphazardly / along the narrow lane / blocking shop entrances / and leaving no clear path for pedestrians.','haphazardly 修饰 were placed，说明摆放方式随机混乱。','摊位无序阻挡通道，符合该副词义。')],mistakes:[M('The chairs were placed haphazardly in exact rows with identical gaps and a numbered seating chart.','The chairs were arranged neatly in exact rows with identical gaps.','精确成行且间距一致不是杂乱摆放。')],quiz:[Q('haphazardly',1,1,'To arrange files haphazardly is to arrange them?','randomly and without order','by a complete alphabetical system','according to a strict plan','randomly and without order','haphazardly 指随意、无序地。'),Q('haphazardly',2,1,'Which placement is haphazardly done?','chairs scattered at uneven angles','chairs aligned in numbered rows','tools returned to labeled drawers','chairs scattered at uneven angles','角度不一、随意散放体现 haphazardly。'),Q('haphazardly',3,1,'The suffix -ly turns haphazard into?','an adverb describing manner','the name of a person','a plural noun','an adverb describing manner','-ly 将形容词构成方式副词。','word-formation'),Q('haphazardly',4,1,'If supplies are stored haphazardly, workers may?','waste time searching for them','find every item instantly by label','know exactly where each item is','waste time searching for them','无序存放会让寻找耗时。')]});
D('happen',{etymology:E('Happen came through Middle English from a Scandinavian source related to happenstance and hap, “chance.” It means take place, occur by chance, or affect someone unexpectedly.','happen'),contexts:[C('happen.s3','意外遭遇','A sudden power cut happened to the laboratory during the overnight test, so the backup system had to preserve the samples.','夜间测试期间实验室突然遭遇停电，因此备用系统必须保护样本。','A sudden power cut happened to the laboratory / during the overnight test / so the backup system / had to preserve the samples.','happened to 在此表示意外发生在某处或影响某人。','停电意外影响实验室，符合 s3。')],mistakes:[M('Nothing happened to the samples during the outage, although every sample was destroyed by the power failure.','Something serious happened to the samples during the outage: the power failure destroyed them.','样本全部损毁与“没有任何事发生”互相矛盾。')],quiz:[Q('happen',1,1,'A meeting happens when it?','takes place','is only planned but never occurs','is stored in a hamper','takes place','s1 指发生、举行。'),Q('happen',2,2,'If I happen to meet your cousin, I meet them?','by chance','after arranging a formal appointment','only in a dream','by chance','s2 表示碰巧做某事。'),Q('happen',3,3,'What happened to the village in the flood? asks?','what affected or occurred to it','who built its handbook','how many hands it has','what affected or occurred to it','s3 可问某人或某地遭遇了什么。'),Q('happen',4,1,'A storm may happen without being?','planned','noticed by anyone','a real event','planned','意外天气事件并非预先计划。')]});
D('happen again',{etymology:E('Happen again is the phrasal expression happen plus again, meaning that an event occurs one more time after an earlier occurrence.','happen again'),contexts:[C('happen again.s1','安全复盘','The crew changed the inspection schedule to keep the valve failure from happening again during the winter shutdown.','维修组调整了检查安排，避免阀门故障在冬季停机期间再次发生。','The crew changed the inspection schedule / to keep the valve failure / from happening again / during the winter shutdown.','happen again 表示某事再次发生。','新安排旨在防止故障重现，匹配该短语。')],mistakes:[M('The team said the leak would happen again, but also promised that it could never recur under any circumstances.','The team said the leak might happen again unless the repair was improved.','承诺绝不复发与说会再次发生在逻辑上冲突。')],quiz:[Q('happen again',1,1,'If a mistake happens again, it?','occurs one more time','has never occurred before','is handed to a colleague','occurs one more time','again 表示重复发生。'),Q('happen again',2,1,'A repair is tested to ensure the fault does not?','happen again','happen yesterday','become a handbook','happen again','维修测试可验证故障是否会重现。'),Q('happen again',3,1,'“Could this happen again?” asks whether it may?','recur','be moved by hand','become a hard hat','recur','happen again 即再次发生。'),Q('happen again',4,1,'Which phrase means recur?','happen again','hand over','hang out','happen again','happen again 是再次发生的表达。')]});
D('happen to',{etymology:E('Happen to combines happen with to and is used when someone does something by chance, as in “I happened to see her.”','happen to'),contexts:[C('happen to.s1','偶遇发现','I happened to notice the warning light while passing the control panel, so I stopped the machine before it overheated.','我经过控制面板时碰巧注意到警示灯，于是在机器过热前将它停了下来。','I happened to notice the warning light / while passing the control panel / so I stopped the machine / before it overheated.','happened to notice 表示碰巧注意到。','观察并非刻意寻找，而是在经过时偶然发生。')],mistakes:[M('I happened to inspect the exact sealed box by chance, after deliberately opening and searching that box for an hour.','I deliberately inspected the sealed box after searching it for an hour.','刻意搜查一小时不属于 happened to 的偶然行为。')],quiz:[Q('happen to',1,1,'“I happened to see the note” means?','I saw it by chance','I planned to write it','I handed it in','I saw it by chance','happen to do 表示碰巧做某事。'),Q('happen to',2,1,'Which sentence uses happen to correctly?','We happened to meet at the station.','We happened the station to meet.','We happen to met at the station.','We happened to meet at the station.','结构为 happen to + 动词原形。','grammar'),Q('happen to',3,1,'If you happen to have a spare key, you?','may have one by chance','must have made it deliberately','will hand it over tomorrow','may have one by chance','该表达常引出偶然拥有或发生的情况。'),Q('happen to',4,1,'The phrase happen to is closest to?','do something accidentally or by chance','force someone to do something','repeat an action exactly','do something accidentally or by chance','happen to 表示偶然发生。')]});
D('happily',{etymology:E('Happily is formed from happy plus -ly. It means with pleasure or contentment, and can also mean fortunately or willingly depending on context.','happily'),contexts:[C('happily.s2','转机报道','The hikers were happily rescued before nightfall when a ranger spotted their signal from the ridge.','护林员在山脊上看到信号，徒步者们幸运地在天黑前获救。','The hikers were happily rescued / before nightfall / when a ranger / spotted their signal from the ridge.','happily 在此表示幸运地，说明救援及时。','获救及时是幸运结果，对应 s2。')],mistakes:[M('The hikers were happily rescued, but no one came and they remained lost overnight.','The hikers were not rescued and remained lost overnight.','无人救援且继续迷路，不符合 happily rescued 的结果。')],quiz:[Q('happily',1,1,'A child sings happily when singing?','with pleasure','against their will','in a random order','with pleasure','s1 指快乐地做某事。'),Q('happily',2,2,'“Happily, the keys were found” means?','fortunately, the keys were found','the keys were found unwillingly','the keys were found in a handbag','fortunately, the keys were found','句首 happily 可表示幸好、幸运的是。'),Q('happily',3,1,'They happily agreed to help. This most likely means they agreed?','willingly and with pleasure','only after being forced','without understanding the request','willingly and with pleasure','happily 可表示乐意地。'),Q('happily',4,2,'Which event ended happily in the “fortunately” sense?','a lost child was safely reunited with family','a storm destroyed the rescue boat','the keys remained missing','a lost child was safely reunited with family','安全团聚是幸运的好结果。')]});
D('happiness',{etymology:E('Happiness is formed from happy plus -ness, with the y changing to i before the suffix. It means the state or feeling of great joy.','happiness'),contexts:[C('happiness.s1','生活感受','For Anika, happiness came from quiet evenings with her family rather than from expensive gifts or public recognition.','对阿妮卡来说，幸福来自与家人共度的宁静夜晚，而非昂贵礼物或公众认可。','For Anika / happiness came from quiet evenings with her family / rather than from expensive gifts / or public recognition.','happiness 是快乐、幸福的感受或状态。','与家人相处带来内心满足，符合词义。')],mistakes:[M('Her happiness was a feeling of intense grief and distress that made her celebrate no good moments.','Her sadness was a feeling of grief and distress that left her unable to enjoy good moments.','强烈悲痛不是 happiness。')],quiz:[Q('happiness',1,1,'Happiness is a feeling of?','joy and contentment','physical hardness','repeated attack','joy and contentment','happiness 指快乐、幸福。'),Q('happiness',2,1,'Which moment could bring happiness?','a peaceful reunion with a loved one','a lost wallet never recovered','a failed safety system','a peaceful reunion with a loved one','团聚可能带来幸福感。'),Q('happiness',3,1,'Happiness is the noun related to?','happy','handy','hard','happy','happiness 由 happy 加 -ness 构成。','word-formation'),Q('happiness',4,1,'Can happiness come from simple daily experiences?','Yes, it can.','No, only expensive things can cause it.','Only when someone is at work.','Yes, it can.','幸福也可来自平常的愉快时刻。')]});
D('happy',{etymology:E('Happy comes from Middle English hap, “chance or fortune,” with -y. Its senses include feeling joy, being satisfied or willing, and something fortunate or well-chosen.','happy'),contexts:[C('happy.s3','表达措辞','The editor called “a well-chosen pause” a happy phrase because it captured the speaker’s relief in just a few words.','编辑称“恰到好处的停顿”是个巧妙的说法，因为它用寥寥几字就表达了说话者的释然。','The editor called “a well-chosen pause” a happy phrase / because it captured the speaker’s relief / in just a few words.','happy 在此指措辞恰当、巧妙。','短语准确传达情绪，符合 s3。')],mistakes:[M('The editor called the happy phrase poorly chosen because it expressed precisely the opposite of the intended meaning.','The editor called the phrase ill-chosen because it expressed the opposite meaning.','表达相反意思的措辞不恰当，不能称为 happy phrase。')],quiz:[Q('happy',1,1,'A happy child is?','feeling pleasure or joy','physically firm and solid','a person who hangs clothes','feeling pleasure or joy','s1 指快乐、幸福的。'),Q('happy',2,2,'“I am happy to help” means the speaker is?','willing to help','angry about helping','unable to help','willing to help','s2 可表示乐意做某事。'),Q('happy',3,3,'A happy coincidence is?','a fortunate event','a difficult task','a repeated attack','a fortunate event','s3 可表示幸运或恰当。'),Q('happy',4,2,'If a customer is happy with a repair, they are?','satisfied with it','still waiting for it','trying to damage it','satisfied with it','s2 也指对某事满意。')]});
D('harass',{etymology:E('Harass entered English from French harasser; the earlier origin is uncertain. It means subject someone to repeated annoyance or attack, and can also refer to unwanted sexual advances.','harass'),contexts:[C('harass.s3','职场行为','The manager was warned not to harass the employee with unwanted sexual comments after she had clearly asked him to stop.','在员工明确要求停止后，经理被警告不得再用不受欢迎的性暗示言论骚扰她。','The manager was warned / not to harass the employee / with unwanted sexual comments / after she had clearly asked him to stop.','harass 在此指进行不受欢迎的性骚扰。','明确要求停止后仍持续作出相关言论，符合 s3。')],mistakes:[M('The manager harassed no one because he respected the employee’s request, stopped all comments, and made no further contact.','The manager respected the employee’s request and did not harass her.','停止行为并尊重界限，不构成持续骚扰。')],quiz:[Q('harass',1,1,'To harass a neighbour is to?','annoy or worry them repeatedly','help them move house once','write a handbook for them','annoy or worry them repeatedly','s1 指反复烦扰。'),Q('harass',2,2,'A force may harass an enemy by?','making repeated attacks','offering a peace award','handing over a map','making repeated attacks','s2 指反复袭扰敌方。'),Q('harass',3,3,'Sexually harass someone is to?','make unwanted sexual advances','ask a neutral work question once','give a safety handout','make unwanted sexual advances','s3 指不受欢迎的性挑逗。'),Q('harass',4,1,'Repeated unwanted messages after a clear request to stop may?','harass the recipient','make the recipient a hamlet','count as a handbook','harass the recipient','持续违背要求的打扰可能构成骚扰。')]});
D('harassment',{etymology:E('Harassment is formed from harass plus -ment. It names unwanted conduct that violates a person’s dignity or creates a hostile environment, especially in workplaces.','harassment'),contexts:[C('harassment.s1','职场政策','The company’s harassment policy explains how staff can report repeated humiliating comments and how complaints will be investigated confidentially.','公司的骚扰政策说明员工如何举报反复羞辱性言论，以及投诉将如何保密调查。','The company’s harassment policy / explains how staff can report / repeated humiliating comments / and how complaints will be investigated confidentially.','harassment 指违背意愿、损害尊严或造成敌意环境的不当行为。','反复羞辱言论属于职场骚扰政策处理范围。')],mistakes:[M('The report dismissed repeated unwanted conduct as harmless even though it humiliated the employee and created a hostile workplace.','The report treated repeated unwanted conduct as harassment because it humiliated the employee and created a hostile workplace.','持续不受欢迎并制造敌意环境的行为不应称为无害。')],quiz:[Q('harassment',1,1,'Workplace harassment may involve conduct that?','violates dignity or creates a hostile environment','is always a single friendly greeting','improves workplace safety','violates dignity or creates a hostile environment','该词强调不受欢迎、损害尊严的行为。'),Q('harassment',2,1,'A workplace policy on harassment should explain?','how to report and investigate complaints','how to repair a hard hat','how to create a hamlet','how to report and investigate complaints','政策应说明举报与调查流程。'),Q('harassment',3,1,'Repeated humiliating comments after objections may constitute?','harassment','a happy coincidence','hands-on training','harassment','反复羞辱性言论可构成骚扰。'),Q('harassment',4,1,'The suffix -ment in harassment forms a noun for?','the conduct or state of harassing','a person’s cheerful mood','a type of phone part','the conduct or state of harassing','-ment 构成行为或状态名词。','word-formation')]});
D('harbor',{etymology:E('Harbor is from Old English herebeorg, originally a shelter or refuge; the verb developed the sense of giving shelter or keeping something within. It names a sheltered port, a place of safety, or the acts of holding a thought or sheltering a wanted person.','harbor'),contexts:[C('harbor.s4','刑事调查','Investigators charged the driver with harboring the fugitive after he hid the wanted man in a locked storage room.','通缉犯被藏在上锁的储藏室后，调查人员指控司机窝藏逃犯。','Investigators charged the driver / with harboring the fugitive / after he hid the wanted man / in a locked storage room.','harboring 在此是藏匿并包庇被追捕者。','司机明知对方被通缉仍藏匿他，符合 s4。')],mistakes:[M('The driver was charged with harboring the fugitive even though he reported the man’s location and never concealed him.','The driver reported the fugitive’s location and did not harbor him.','主动报告位置且未藏匿，不符合窝藏义。')],quiz:[Q('harbor',1,1,'A harbor is a sheltered place where?','ships can stay safely','workers store hard hats','people write by hand','ships can stay safely','s1 指船只避风停泊的港口。'),Q('harbor',2,2,'A small cabin may harbor a lost traveller by?','providing shelter and safety','making the person work harder','turning into a harbor port','providing shelter and safety','s2 是庇护、藏身处。'),Q('harbor',3,3,'To harbor resentment is to?','keep the feeling for a long time','forget it immediately','hand it over to a colleague','keep the feeling for a long time','s3 指心中长期怀有情感。'),Q('harbor',4,4,'To harbor a fugitive is to?','hide and protect a wanted person','help police locate them','build a dock for ships','hide and protect a wanted person','s4 指藏匿、包庇被追捕者。')]});
D('hard',{etymology:E('Hard comes from Old English heard, from a Germanic root. It can describe physical firmness, difficulty, effort, working with effort, or forceful action.','hard'),contexts:[C('hard.s4','训练记录','The rowers trained hard before sunrise, repeating the same sequence until every stroke remained synchronized under fatigue.','赛艇队员日出前刻苦训练，不断重复同一套动作，直到疲劳时每一桨仍保持同步。','The rowers trained hard before sunrise / repeating the same sequence / until every stroke remained synchronized / under fatigue.','hard 在此作副词，修饰 trained，表示努力地、费力地。','反复训练并克服疲劳体现 s4。')],mistakes:[M('The rowers trained hard by avoiding all practice and stopping as soon as the session began.','The rowers trained hard by practising repeatedly and sustaining effort.','完全不练习与刻苦训练相矛盾。')],quiz:[Q('hard',1,1,'A hard surface is?','firm and not easy to bend','soft and easily crushed','a helpful gesture','firm and not easy to bend','s1 指坚硬的。'),Q('hard',2,2,'A hard examination is?','difficult','made of steel','generous in amount','difficult','s2 表示困难。'),Q('hard',3,3,'A hard-working employee shows?','a lot of effort','little attention to work','a preference for easy tasks only','a lot of effort','s3 指勤奋、出力多。'),Q('hard',4,5,'The ball hit the wall hard. It hit with?','great force','no contact','a soft whisper','great force','s5 表示用力、猛烈地。')]});
D('hard hat',{etymology:E('Hard hat is a compound phrase combining hard and hat. It names a protective helmet worn by construction and other workers to reduce head injuries.','hard hat'),contexts:[C('hard hat.s1','建筑工地','Visitors had to wear a hard hat before entering the renovation site, where loose tools and debris could fall from upper floors.','访客进入翻修工地前必须戴安全帽，因为高层可能有松动工具和碎屑坠落。','Visitors had to wear a hard hat / before entering the renovation site / where loose tools and debris / could fall from upper floors.','hard hat 指工人佩戴的安全头盔。','防止坠落物造成头部伤害是安全帽的用途。')],mistakes:[M('The site manager required a hard hat to protect visitors’ feet from falling debris.','The site manager required a hard hat to protect visitors’ heads from falling debris.','安全帽用于保护头部，不是脚部。')],quiz:[Q('hard hat',1,1,'A worker wears a hard hat to protect the?','head','hands from ink','knees from cold','head','hard hat 是安全帽。'),Q('hard hat',2,1,'A construction visitor may need a hard hat because?','objects could fall from above','the site is too quiet','a handbook is heavy','objects could fall from above','安全帽防范坠物伤头。'),Q('hard hat',3,1,'Which item is a hard hat?','a protective work helmet','a knitted winter scarf','a telephone handset','a protective work helmet','hard hat 指工地防护头盔。'),Q('hard hat',4,1,'The compound hard hat names a hat that is?','made for protective use','used to hand in homework','a small orange','made for protective use','词组指坚固的防护帽。','word-formation')]});
D('hard of hearing',{etymology:E('Hard of hearing is an idiomatic adjective phrase using hard in the sense of “not easily able.” It describes someone who has difficulty hearing; it does not necessarily mean complete deafness.','hard of hearing'),contexts:[C('hard of hearing.s1','公共服务','The meeting organizer provided a live caption screen for guests who were hard of hearing and checked that every speaker used the microphone.','会议组织者为听力受损的来宾提供实时字幕屏，并确保每位发言者都使用麦克风。','The meeting organizer provided a live caption screen / for guests who were hard of hearing / and checked / that every speaker used the microphone.','hard of hearing 描述听力有困难的人，并不等同于完全失聪。','字幕与麦克风改善有听力困难者的参与条件。')],mistakes:[M('The guide called a hard-of-hearing visitor completely unable to hear any sound, although the visitor heard speech with an aid.','The guide said the visitor was hard of hearing and could hear speech with an aid.','听力受损不必然意味着完全听不见任何声音。')],quiz:[Q('hard of hearing',1,1,'A person who is hard of hearing?','has difficulty hearing','cannot see clearly','has difficulty using a hard hat','has difficulty hearing','该短语指听力受损。'),Q('hard of hearing',2,1,'A live caption screen can help guests who are?','hard of hearing','hard-working','hardheaded','hard of hearing','实时字幕为听力困难者提供文字信息。'),Q('hard of hearing',3,1,'Does hard of hearing always mean totally deaf?','No; hearing may be reduced but not absent.','Yes; it always means no sound can be heard.','Only when a person uses a handset.','No; hearing may be reduced but not absent.','该词指听力困难，不一定完全失聪。'),Q('hard of hearing',4,1,'Which accommodation may help a hard-of-hearing participant?','clear microphones and captions','a silent speaker with no captions','a soft hat covering the ears','clear microphones and captions','声音增强和字幕可帮助听力受损者。')]});
D('hard work',{etymology:E('Hard work combines hard in the sense of requiring effort with work. It means a task or activity that demands great effort.','hard work'),contexts:[C('hard work.s1','社区建设','Restoring the flood-damaged footbridge took hard work from residents who hauled timber, cleared mud, and replaced the broken supports.','修复被洪水损坏的人行桥需要居民付出艰苦劳动：他们搬木料、清淤泥并更换断裂支撑。','Restoring the flood-damaged footbridge took hard work / from residents who hauled timber / cleared mud / and replaced the broken supports.','hard work 指需要付出很大努力的劳动。','搬木料、清淤和更换支撑都费时费力。')],mistakes:[M('The bridge restoration was hard work because it required no effort, time, or physical activity from anyone.','The bridge restoration was effortless because it required no time or physical activity.','不需要努力的工作不能称为 hard work。')],quiz:[Q('hard work',1,1,'Hard work requires?','great effort','no action at all','only a written signature','great effort','hard work 指费力的劳动。'),Q('hard work',2,1,'Which is an example of hard work?','repairing a storm-damaged bridge','watching a short video','resting beside a finished bridge','repairing a storm-damaged bridge','搬运和修复需要持续投入。'),Q('hard work',3,1,'A student describes revision as hard work when it?','takes sustained concentration and effort','requires no attention','is completed without reading','takes sustained concentration and effort','学习复习需要专注和努力。'),Q('hard work',4,1,'Hard work is closest in meaning to?','strenuous effort','a protective helmet','a rare orange','strenuous effort','该词组强调艰苦付出。')]});
D('hard-working',{etymology:E('Hard-working combines hard with the present participle working. It describes a person or animal that works with energy and care.','hard-working'),contexts:[C('hard-working.s1','农场经营','The hard-working crew repaired irrigation lines before dawn so the seedlings would receive water during the hottest part of the day.','勤奋的施工队在黎明前修好了灌溉管线，让幼苗能在一天最热的时候得到水。','The hard-working crew repaired irrigation lines before dawn / so the seedlings / would receive water / during the hottest part of the day.','hard-working 描写做事努力、认真投入的团队。','团队在清晨提前完成维修，体现勤奋。')],mistakes:[M('The hard-working apprentice refused every task, arrived late each day, and made no effort to learn the craft.','The idle apprentice refused tasks and made no effort to learn the craft.','拒绝工作且不投入，与 hard-working 相反。')],quiz:[Q('hard-working',1,1,'A hard-working person?','puts energy and care into tasks','avoids every task','only works when watched','puts energy and care into tasks','hard-working 指努力工作的。'),Q('hard-working',2,1,'Which employee is hard-working?','one who stays focused and finishes careful repairs','one who abandons each task unfinished','one who sleeps through every shift','one who stays focused and finishes careful repairs','专注并认真完成任务体现勤奋。'),Q('hard-working',3,1,'A hard-working team may?','prepare early to meet a deadline','wait until the deadline passes','discard all tools','prepare early to meet a deadline','提前准备以完成任务体现认真努力。'),Q('hard-working',4,1,'The hyphenated adjective describes someone who?','works energetically and carefully','is difficult to hear','owns a hard hat','works energetically and carefully','hard + working 组成描述工作态度的形容词。','word-formation')]});
D('harden',{etymology:E('Harden is formed from hard plus the verb suffix -en. It means become hard or make something hard; the assigned source sense covers the intransitive change.','harden'),contexts:[C('harden.s1','材料变化','The clay began to harden as it dried in the open air, so the potter covered it before the surface became too firm to shape.','黏土在空气中干燥时开始变硬，因此陶艺师在表面硬到无法塑形前把它盖了起来。','The clay began to harden / as it dried in the open air / so the potter covered it / before the surface became too firm to shape.','harden 在此是不及物动词，表示逐渐变硬。','水分蒸发使黏土变硬，符合 s1。')],mistakes:[M('The wet clay hardened by becoming softer and more liquid as it sat uncovered.','The wet clay softened as it became more liquid while uncovered.','变得更软、更液态不是 harden。')],quiz:[Q('harden',1,1,'When wet clay hardens, it?','becomes firm or solid','turns into a liquid','is handed to a worker','becomes firm or solid','harden 指变硬。'),Q('harden',2,1,'A coating may harden as it?','dries or cools','is diluted with more water','is turned into a handbook','dries or cools','干燥或冷却可能令材料变硬。'),Q('harden',3,1,'Which change means harden?','soft wax becomes firm','firm clay becomes liquid','a worker takes a break','soft wax becomes firm','由软变硬符合该动词。'),Q('harden',4,1,'The suffix -en in harden helps form a verb meaning?','become or make hard','write by hand','form a small village','become or make hard','-en 可构成表示变化的动词。','word-formation')]});
D('hardheaded',{etymology:E('Hardheaded combines hard and head. Figuratively it can mean practical and unsentimental, or stubbornly unwilling to change an opinion.','hardheaded'),contexts:[C('hardheaded.s2','谈判评价','The hardheaded negotiator refused to reconsider the proposal even after the new cost estimate disproved his main objection.','这位顽固的谈判者即使在新的成本估算推翻其主要反对理由后，也拒绝重新考虑方案。','The hardheaded negotiator refused to reconsider the proposal / even after the new cost estimate / disproved / his main objection.','hardheaded 在此表示固执、不肯改变看法。','已有新证据仍拒绝重审观点，符合 s2。')],mistakes:[M('The hardheaded negotiator immediately changed his view when the evidence arrived and welcomed every correction.','The flexible negotiator changed his view when the evidence arrived.','乐于根据证据修正观点，不符合固执的 hardheaded 义。')],quiz:[Q('hardheaded',1,1,'A hardheaded business owner in the practical sense?','makes decisions based on facts rather than emotion','changes every decision at random','refuses to examine any costs','makes decisions based on facts rather than emotion','s1 指务实、讲实际。'),Q('hardheaded',2,2,'A hardheaded person who ignores new evidence is?','stubborn','easily persuaded','generous with money','stubborn','s2 指顽固、不肯改主意。'),Q('hardheaded',3,1,'A hardheaded budget review focuses on?','practical costs and likely results','wishful thinking alone','decorative handwriting','practical costs and likely results','务实判断关注实际成本和结果。'),Q('hardheaded',4,2,'Which response sounds hardheaded in the stubborn sense?','“I will not reconsider, even after the facts change.”','“I was wrong; I will update my view.”','“Let us compare the new evidence.”','“I will not reconsider, even after the facts change.”','拒绝因新证据而改变观点体现顽固。')]});
D('hardliner',{etymology:E('Hardliner is formed from hard line plus -er, naming a person who insists on a strict or uncompromising position, especially in politics or negotiations.','hardliner'),contexts:[C('hardliner.s1','政治谈判','The hardliner rejected even the temporary ceasefire, insisting that the government accept every demand before talks could begin.','这名强硬派连临时停火都拒绝，坚称政府必须先接受全部要求，谈判才能开始。','The hardliner rejected even the temporary ceasefire / insisting that the government accept every demand / before talks / could begin.','hardliner 指坚持严格、强硬立场的人。','拒绝妥协并要求全部接受，体现强硬路线。')],mistakes:[M('The hardliner readily compromised on every demand and accepted any proposal without conditions.','The negotiator readily compromised on every demand and accepted proposals without conditions.','毫无条件地妥协与坚持强硬路线相反。')],quiz:[Q('hardliner',1,1,'A political hardliner usually?','insists on a strict, uncompromising position','changes position with every poll','avoids taking any view','insists on a strict, uncompromising position','hardliner 指强硬派。'),Q('hardliner',2,1,'A hardliner in negotiations may reject?','a compromise agreement','a firm demand','a strict position','a compromise agreement','强硬派往往不愿接受妥协方案。'),Q('hardliner',3,1,'The word hardliner is most likely used about?','a person in politics or negotiations','a soft cloth or towel','a phone component','a person in politics or negotiations','该词常描述政治或谈判立场。'),Q('hardliner',4,1,'The element line in hardliner refers figuratively to?','a fixed position or policy','a handwriting sample','a row of orange trees','a fixed position or policy','hard line 表示严格路线。','word-formation')]});
D('hardly',{etymology:E('Hardly is formed from hard plus -ly, but its main sense has developed to “almost not” or “scarcely.” It can soften a negative statement and can mean only just or a short time before.','hardly'),contexts:[C('hardly.s3','行程记录','The train had hardly left the station when the signal failure forced it to stop again less than a kilometre down the line.','火车刚离开车站不久，信号故障就迫使它在不到一公里处再次停下。','The train had hardly left the station / when the signal failure / forced it to stop again / less than a kilometre down the line.','hardly 在此表示“刚刚……就”，与 when 从句搭配。','离站后很短时间便停下，符合 s3。')],mistakes:[M('The train had hardly left the station when it completed a twelve-hour trip and arrived at its destination.','The train had barely left the station when it was forced to stop again.','十二小时行程后到达，不可能是“刚刚离站就发生”的事件。')],quiz:[Q('hardly',1,1,'“I could hardly hear the announcement” means?','I could almost not hear it','I heard every word clearly','I refused to listen on purpose','I could almost not hear it','s1 表示几乎听不见。'),Q('hardly',2,2,'“That is hardly fair” is a softened way to say?','That is not really fair.','That is extremely generous.','That is a hard object.','That is not really fair.','s2 可用于委婉表达否定。'),Q('hardly',3,3,'“Hardly had we arrived when it began to rain” means?','It began to rain just after we arrived.','It rained long before we left home.','We never arrived.','It began to rain just after we arrived.','s3 表示刚发生某事，另一事紧接着发生。'),Q('hardly',4,1,'Which sentence uses hardly to mean scarcely?','There was hardly any fuel left.','The crew worked hard all day.','The hard hat fit well.','There was hardly any fuel left.','hardly any 表示几乎没有。')]});

D('hardly any',{etymology:E('Hardly any combines hardly, “almost not,” with any. It means almost none of the things or amount in question.','hardly any'),contexts:[C('hardly any.s1','库存盘点','There was hardly any flour left in the bakery at closing, so the morning team had to collect fresh sacks before mixing dough.','面包店关门时几乎没有剩余面粉，因此早班员工必须在和面前领取新面粉袋。','There was hardly any flour left / in the bakery at closing / so the morning team / had to collect fresh sacks.','hardly any flour 表示面粉所剩无几。','需要领取新面粉说明库存几乎耗尽。')],mistakes:[M('There was hardly any flour left, meaning the shelves were completely full of fresh bags.','There was plenty of flour left because the shelves were full of fresh bags.','货架堆满新面粉与几乎没有剩余相反。')],quiz:[Q('hardly any',1,1,'“There is hardly any time left” means?','almost no time remains','a large amount of time remains','time has been planned carefully','almost no time remains','hardly any 表示几乎没有。'),Q('hardly any',2,1,'Which shelf has hardly any books?','one with only one book left','one packed from end to end','one with every book in place','one with only one book left','只剩一本表示几乎没有。'),Q('hardly any',3,1,'Hardly any is closest to?','almost none','more than enough','all of them','almost none','该短语表示数量接近零。'),Q('hardly any',4,1,'If hardly any rain fell, the ground likely received?','very little rain','a flood of rain','exactly one full lake','very little rain','hardly any rain 指降雨量很少。')]});
D('hardly ever',{etymology:E('Hardly ever combines hardly, “almost not,” with ever. It means almost never or on very few occasions.','hardly ever'),contexts:[C('hardly ever.s1','日常习惯','Because the coastal bus runs only twice a week, residents hardly ever use it for a same-day appointment in the city.','由于沿海公交每周只运行两次，居民几乎不会搭它当天往返市区赴约。','Because the coastal bus runs only twice a week / residents hardly ever use it / for a same-day appointment / in the city.','hardly ever 修饰 use，表示几乎从不这样使用。','班次稀少使当天往返极少发生。')],mistakes:[M('She hardly ever misses the bus, although she has missed it every single day this month.','She often misses the bus because she has missed it every day this month.','每天都错过公交不符合几乎从不错过。')],quiz:[Q('hardly ever',1,1,'Someone who hardly ever eats out?','almost never eats at restaurants','eats at restaurants every night','has never heard of food','almost never eats at restaurants','hardly ever 指几乎从不。'),Q('hardly ever',2,1,'Which frequency is closest to hardly ever?','once in several years','every morning','three times a day','once in several years','极少发生对应 hardly ever。'),Q('hardly ever',3,1,'“We hardly ever see snow here” means snow is?','very rare here','falling every day','impossible everywhere','very rare here','hardly ever 表示事件罕见。'),Q('hardly ever',4,1,'The phrase hardly ever is about?','frequency','physical hardness','a tool’s handle','frequency','该短语说明发生频率极低。')]});
D('hardness',{etymology:E('Hardness is formed from hard plus -ness. It can mean a material’s resistance to scratching or denting, or figuratively the severity of a manner or situation.','hardness'),contexts:[C('hardness.s2','艰难生活','The memoir describes the hardness of life during the winter blockade, when families lacked fuel and had to ration food.','回忆录描述了冬季封锁期间生活的艰难：家家缺少燃料，不得不定量分配食物。','The memoir describes the hardness of life / during the winter blockade / when families lacked fuel / and had to ration food.','hardness 在此指处境的艰难程度。','缺燃料、限量供食体现艰苦生活。')],mistakes:[M('The memoir calls the winter blockade a time of hardness, although every household had abundant fuel, food, and comfort.','The memoir calls the winter blockade comfortable because every household had abundant supplies.','物资充足且生活舒适不符合艰难处境之义。')],quiz:[Q('hardness',1,1,'A material’s hardness measures how well it resists?','scratching or denting','changing its colour','being written about','scratching or denting','s1 指材料抵抗划伤或压痕的程度。'),Q('hardness',2,2,'The hardness of a difficult period means its?','severity or harshness','surface gloss','number of handouts','severity or harshness','s2 指处境或态度的严酷。'),Q('hardness',3,1,'A diamond’s hardness is relevant when testing?','resistance to scratching','how quickly it melts in water','how loudly it rings','resistance to scratching','硬度与抗划伤能力相关。'),Q('hardness',4,2,'“The hardness of the journey” refers to?','how difficult and severe it was','the firmness of a metal tool','the number of miles only','how difficult and severe it was','该搭配指旅途的艰难程度。')]});
D('hardship',{etymology:E('Hardship is formed from hard plus -ship. It names a difficult condition or a particular painful experience that someone must endure.','hardship'),contexts:[C('hardship.s2','个人经历','After the wildfire destroyed her home, Mira described the months in temporary housing as the hardest hardship she had faced.','野火烧毁房子后，米拉把住临时住所的几个月称为自己经历过的最艰难困境。','After the wildfire destroyed her home / Mira described the months in temporary housing / as the hardest hardship / she had faced.','hardship 在此指个人经历的一段苦难。','火灾后住临时住所是一段具体艰难经历，符合 s2。')],mistakes:[M('The family called a week at a luxury resort a hardship even though all their needs were met and no difficulty arose.','The family enjoyed a comfortable week at a luxury resort with no hardship.','需求都得到满足且没有困难，不构成苦难经历。')],quiz:[Q('hardship',1,1,'A community may face hardship when?','basic living conditions become very difficult','all services work perfectly','a handbook is published','basic living conditions become very difficult','s1 指生活境况艰苦。'),Q('hardship',2,2,'A person’s hardship can be?','a painful experience they endured','a comfortable holiday','a type of handcraft','a painful experience they endured','s2 指经历过的艰难遭遇。'),Q('hardship',3,1,'Which event creates hardship?','a long drought that ruins crops','a plentiful harvest with stable prices','a day with no responsibilities','a long drought that ruins crops','旱灾破坏庄稼会带来困难。'),Q('hardship',4,1,'Hardship is closest to?','serious difficulty','easy success','a smooth surface','serious difficulty','该词表示艰难、困苦。')]});
D('hardware',{etymology:E('Hardware combines hard and ware, originally referring to metal goods and tools. It now also names the physical components of a computer and, in military use, heavy equipment or weapons.','hardware'),contexts:[C('hardware.s3','军事预算','The defense report listed aircraft, tracked vehicles, and radar units as military hardware requiring costly maintenance.','国防报告把飞机、履带车辆和雷达设备列为需要高额维护的军事装备。','The defense report listed aircraft, tracked vehicles, and radar units / as military hardware / requiring costly maintenance.','hardware 在此指重型军事装备。','列出的飞机、车辆和雷达属于军事设备。')],mistakes:[M('The report classified a paper notebook and a pencil as heavy military hardware.','The report classified aircraft and armored vehicles as heavy military hardware.','纸笔不是重型军事装备。')],quiz:[Q('hardware',1,1,'A hardware shop sells?','tools and equipment for home or garden','only computer programs','stories about a hamlet','tools and equipment for home or garden','s1 指五金工具和设备。'),Q('hardware',2,2,'A computer’s hardware includes?','its physical components','its written instructions only','the user’s handwriting','its physical components','s2 指计算机实体部件。'),Q('hardware',3,3,'Military hardware may include?','weapons and heavy equipment','a paper handkerchief','a cotton hamper','weapons and heavy equipment','s3 指军事装备或武器。'),Q('hardware',4,2,'Which is computer hardware?','a physical processor chip','a downloaded text file only','an idea in a user’s mind','a physical processor chip','实体处理器属于计算机硬件。')]});
D('hardwired',{etymology:E('Hardwired combines hard and wired. Literally it means connected by fixed electrical wiring; figuratively it can describe a deeply fixed tendency that seems innate.','hardwired'),contexts:[C('hardwired.s2','行为研究','Researchers cautioned that the preference was not hardwired in every infant; experience and culture also shaped how the children responded.','研究人员提醒说，并非每个婴儿都天生具有这种偏好；经验和文化也会影响孩子的反应。','Researchers cautioned / that the preference was not hardwired / in every infant / experience and culture also shaped the responses.','hardwired 在此比喻某种倾向根深蒂固、仿佛天生。','研究者指出经验也会塑造偏好，因此并非固定先天。')],mistakes:[M('The appliance was hardwired to the wall, although it had no cable and connected only through a wireless app.','The appliance was wirelessly connected to the wall system through an app.','无实体固定电线的无线连接不属于字面义 hardwired。')],quiz:[Q('hardwired',1,1,'A hardwired alarm is?','connected by fixed electrical wires','controlled only by a handwritten note','a wooden object','connected by fixed electrical wires','s1 指固定接线连接。'),Q('hardwired',2,2,'A hardwired reaction is figuratively?','deeply fixed or seemingly innate','chosen for the first time today','a computer cable','deeply fixed or seemingly innate','s2 表示根深蒂固、似乎天生。'),Q('hardwired',3,1,'Which device is literally hardwired?','a thermostat connected by permanent cable','a speaker linked only by Bluetooth','a battery-powered toy with no wires','a thermostat connected by permanent cable','永久布线连接符合字面义。'),Q('hardwired',4,2,'If fear seems hardwired, it seems?','deeply built into behaviour','easy to remove with a cable','related to hardwood trees','deeply built into behaviour','比喻义强调固定、内在。')]});
D('hardwood',{etymology:E('Hardwood combines hard and wood. In forestry it means timber from angiosperm trees such as oak and maple, as opposed to coniferous softwood; the botanical category does not guarantee every species is physically harder.','hardwood'),contexts:[C('hardwood.s1','木材选购','The carpenter chose oak hardwood for the stair treads because it wears well under frequent foot traffic and can be refinished.','木匠为楼梯踏板选择橡木硬木，因为它耐频繁踩踏且可以重新打磨上漆。','The carpenter chose oak hardwood for the stair treads / because it wears well / under frequent foot traffic / and can be refinished.','hardwood 指来自橡树等被子植物树木的木材类别。','橡木属于阔叶硬木，常用于耐磨木作。')],mistakes:[M('The forester classified pine, a conifer, as hardwood solely because every hardwood species is physically soft.','The forester classified pine as softwood because it comes from a conifer.','松树是针叶树，木材类别为 softwood；hardwood 分类不是按每块木材的触感决定。')],quiz:[Q('hardwood',1,1,'Hardwood timber generally comes from?','angiosperm trees such as oak or maple','all conifers only','cotton plants','angiosperm trees such as oak or maple','s1 指阔叶被子植物树木的木材。'),Q('hardwood',2,1,'Which wood is typically hardwood?','oak','pine','spruce','oak','橡木属于 hardwood。'),Q('hardwood',3,1,'Does the category hardwood guarantee every species is physically harder than every softwood?','No; it is a botanical timber category.','Yes, without exception.','Only after it is painted.','No; it is a botanical timber category.','名称源于树木类别，不代表绝对硬度对比。'),Q('hardwood',4,1,'Hardwood is often used for?','durable flooring or furniture','a telephone earpiece','a written handout','durable flooring or furniture','耐用木材常用于地板和家具。')]});
D('hardworking',{etymology:E('Hardworking combines hard and working. It is an adjective meaning putting substantial effort into work; hardworking is commonly written without a hyphen.','hardworking'),contexts:[C('hardworking.s1','社区志愿','A hardworking volunteer crew sorted the donated books late into the evening so the rural library could reopen on Monday.','一群勤奋的志愿者工作到深夜整理捐赠图书，好让乡村图书馆周一重新开放。','A hardworking volunteer crew sorted the donated books / late into the evening / so the rural library / could reopen on Monday.','hardworking 描写投入大量精力工作的团队。','他们加班整理书籍以按时开放，体现勤奋。')],mistakes:[M('The hardworking crew abandoned every task, refused to sort the books, and made no effort to reopen the library.','The idle crew abandoned the tasks and made no effort to reopen the library.','完全不做事与 hardworking 相反。')],quiz:[Q('hardworking',1,1,'A hardworking student?','puts consistent effort into studying','avoids every assignment','never attends class','puts consistent effort into studying','hardworking 表示勤奋的。'),Q('hardworking',2,1,'Which team is hardworking?','one that carefully finishes a large task','one that leaves all work undone','one that loses the instructions','one that carefully finishes a large task','认真完成工作体现勤奋。'),Q('hardworking',3,1,'Hardworking is usually written?','as one word','with a mandatory hyphen','as two unrelated words','as one word','该形容词常连写。','spelling'),Q('hardworking',4,1,'A hardworking nurse might?','stay focused while caring for patients','ignore every patient request','sleep through an entire shift','stay focused while caring for patients','持续投入工作符合勤奋义。')]});
D('hardy',{etymology:E('Hardy came through Old French hardi, “bold or courageous.” Its English senses include plants able to withstand cold, people able to endure hardship, and someone bold or unafraid.','hardy'),contexts:[C('hardy.s1','园艺种植','The gardener chose hardy perennials that could survive the exposed hillside through freezing nights and return the following spring.','园丁选择耐寒的多年生植物，让它们能在无遮蔽山坡上熬过冰冻夜晚，并于次年春天再度生长。','The gardener chose hardy perennials / that could survive the exposed hillside / through freezing nights / and return the following spring.','hardy 修饰 perennials，指植物耐寒、经得起恶劣天气。','植物能挺过霜冻并返青，符合 s1。')],mistakes:[M('The gardener planted tender plants that died at the first light frost and called them hardy.','The gardener planted hardy plants that survived the frost.','遇到轻霜就死亡的娇嫩植物不能称为 hardy。')],quiz:[Q('hardy',1,1,'A hardy plant can?','survive cold or difficult conditions','grow only in warm glasshouses','never need water','survive cold or difficult conditions','s1 指植物耐寒。'),Q('hardy',2,2,'A hardy worker is?','strong and able to endure hardship','easily discouraged by small tasks','a type of tree','strong and able to endure hardship','s2 指耐劳坚强。'),Q('hardy',3,3,'A hardy explorer may be?','bold and unafraid','afraid to leave a warm room','a phone component','bold and unafraid','s3 指大胆无畏。'),Q('hardy',4,1,'Which garden plant is hardy?','one that survives a freezing winter','one that dies in mild cold','one made from paper','one that survives a freezing winter','耐霜冻体现植物 hardy。')]});
D('hare',{etymology:E('Hare comes from Old English hara, from a Germanic root. It names a fast wild mammal resembling a rabbit but generally larger, with long hind legs and long ears.','hare'),contexts:[C('hare.s1','草原观察','At dusk, a hare sprinted across the open field and vanished into tall grass before the photographer could focus the lens.','黄昏时，一只野兔飞快地穿过开阔田野，在摄影师对准镜头前就消失在高草中。','At dusk / a hare sprinted across the open field / and vanished into tall grass / before the photographer could focus the lens.','hare 指长耳、后腿有力、奔跑迅速的野生兔形动物。','快速穿越草地并躲进草丛符合野兔特征。')],mistakes:[M('The hare was a domesticated fish that swam through the field and breathed through gills.','The hare was a fast wild mammal that ran across the field.','野兔是陆生哺乳动物，不是会用鳃呼吸的鱼。')],quiz:[Q('hare',1,1,'A hare is a fast wild?','rabbit-like mammal','freshwater fish','small goose','rabbit-like mammal','hare 是野生兔形哺乳动物。'),Q('hare',2,1,'A hare can sprint quickly because it has?','long powerful hind legs','cotton cheek pouches','a hammer-shaped head','long powerful hind legs','长而有力的后腿适于奔跑。'),Q('hare',3,1,'Which habitat could a hare cross at dusk?','an open field','the inside of a phone handset','a glass furnace','an open field','野兔会在草地等开阔地活动。'),Q('hare',4,1,'A hare differs from a goldfish because it?','is a land mammal','breathes with gills','lives only underwater','is a land mammal','野兔是陆生哺乳动物。')]});
D('harem',{etymology:E('Harem entered English through Turkish and Arabic, related to Arabic harim, a protected or forbidden place. Historically it referred to the women’s quarters of some households or the wives and concubines living there; use the term with its cultural and historical context.','harem'),contexts:[C('harem.s1','历史建筑','The museum’s exhibit describes the harem as a private residential area in a historical palace and explains how the household was organized.','博物馆展览把 harem 介绍为历史宫殿中的私人居住区域，并解释了当时家庭空间如何安排。','The museum’s exhibit describes the harem / as a private residential area / in a historical palace / and explains how the household was organized.','harem 在此指某些历史社会中宅邸内女性居住的区域。','展览将该词放在宫殿住宅史的具体语境中。')],mistakes:[M('The guide claimed that harem was the name of a public courtroom open to every visitor in every society.','The guide described the harem as a private household area in a particular historical context.','该词不是普遍意义上的公共法庭，含义需结合历史文化背景。')],quiz:[Q('harem',1,1,'Historically, a harem could refer to?','a household area reserved for women in some societies','a public railway station','a type of hand tool','a household area reserved for women in some societies','harem 有特定历史文化含义。'),Q('harem',2,1,'A museum should explain the term harem with?','its historical and cultural context','a claim that it describes all households everywhere','no context at all','its historical and cultural context','该词使用时应说明语境。'),Q('harem',3,1,'In historical usage, harem could also refer to?','the wives and concubines living in that household','the palace’s public market','a military weapon','the wives and concubines living in that household','词义还可指居住在该区域中的妻妾。'),Q('harem',4,1,'Which description is most careful?','a private household area in certain historical societies','a universal name for a modern bedroom','a synonym for a public office','a private household area in certain historical societies','限定特定历史社会可避免泛化。')]});
D('harm',{etymology:E('Harm comes from Old English hearm, from a Germanic root. It can mean physical injury or damage, damage to feelings or reputation, or the act of hurting or damaging someone or something.','harm'),contexts:[C('harm.s2','声誉影响','The false accusation caused lasting harm to the researcher’s reputation, even after the newspaper printed a correction.','即使报纸刊登了更正，这项虚假指控仍对研究者的声誉造成了持久损害。','The false accusation caused lasting harm / to the researcher’s reputation / even after / the newspaper printed a correction.','harm 在此指对声誉造成的精神或社会损害。','虚假指控损害名誉，符合 s2。')],mistakes:[M('The false accusation caused no harm to her reputation, although colleagues withdrew support and the story spread widely.','The false accusation harmed her reputation when colleagues withdrew support and the story spread.','声誉受损与造成的实际后果相矛盾。')],quiz:[Q('harm',1,1,'Physical harm is?','injury or damage to a person or thing','a generous payment','a small village','injury or damage to a person or thing','s1 指身体或物品受损。'),Q('harm',2,2,'A lie may cause harm to someone’s?','feelings or reputation','handwriting only','hard hat','feelings or reputation','s2 指精神或名誉损害。'),Q('harm',3,3,'To harm a plant is to?','damage or hurt it','help it grow','hand it to a gardener','damage or hurt it','s3 作动词表示伤害、损害。'),Q('harm',4,1,'Which action may harm a person physically?','leaving a dangerous wire exposed','offering a safe handrail','providing clear instructions','leaving a dangerous wire exposed','裸露危险电线可能造成身体伤害。')]});
D('harmful',{etymology:E('Harmful is formed from harm plus -ful, meaning causing harm or damage.','harmful'),contexts:[C('harmful.s1','环境健康','The report warned that burning the treated waste outdoors could release harmful fumes that irritate the lungs and contaminate nearby soil.','报告警告说，在户外焚烧处理过的废料会释放有害烟雾，刺激肺部并污染附近土壤。','The report warned / that burning the treated waste outdoors / could release harmful fumes / that irritate the lungs and contaminate nearby soil.','harmful 修饰 fumes，表示会造成伤害或损害。','烟雾会刺激肺部并污染土壤，符合有害义。')],mistakes:[M('The fumes were harmless and harmful at the same time because they caused no injury but damaged every nearby lung.','The fumes were harmful because they injured nearby lungs.','造成肺部损伤与 harmless 的定义相冲突。')],quiz:[Q('harmful',1,1,'A harmful chemical is one that?','can cause injury or damage','guarantees safety','is easy to carry','can cause injury or damage','harmful 指有害的。'),Q('harmful',2,1,'Which may be harmful to lungs?','toxic fumes','clean fresh air','a clear safety label','toxic fumes','有毒烟雾会损害肺部。'),Q('harmful',3,1,'Harmful is the opposite of?','harmless','handy','hardwood','harmless','harmful 与 harmless 相反。','word-formation'),Q('harmful',4,1,'A harmful rumor may damage?','someone’s reputation','a phone battery only','a coat hanger','someone’s reputation','谣言可能损害名誉。')]});
D('harmfully',{etymology:E('Harmfully is formed from harmful plus -ly. It means in a way that causes damage to health, the environment, or someone’s interests.','harmfully'),contexts:[C('harmfully.s1','产品说明','The solvent was stored harmfully near an open drain, allowing leaks to reach the stream after the container cracked.','溶剂被不当存放在敞开的排水沟旁，容器破裂后泄漏物便流进溪流，造成了危害。','The solvent was stored harmfully near an open drain / allowing leaks / to reach the stream / after the container cracked.','harmfully 修饰 stored，表示以造成损害的方式。','不安全存放使泄漏污染水道，符合该副词义。')],mistakes:[M('The chemical was handled harmfully by using sealed containers, protective gloves, and a closed ventilation system.','The chemical was handled safely by using sealed containers, protective gloves, and closed ventilation.','密封容器、防护手套和通风系统是安全措施，不是有害操作。')],quiz:[Q('harmfully',1,1,'To act harmfully is to act?','in a way that causes damage','in a way that guarantees protection','without affecting anything','in a way that causes damage','harmfully 表示有害地。'),Q('harmfully',2,1,'Which action treats a river harmfully?','dumping untreated chemicals into it','installing a filter before discharge','testing water quality','dumping untreated chemicals into it','排放未处理化学物会造成污染。'),Q('harmfully',3,1,'The suffix -ly in harmfully makes it an adverb of?','manner','person','place name','manner','-ly 描述动作进行的方式。','word-formation'),Q('harmfully',4,1,'A policy that harmfully affects workers?','damages their health or interests','protects their safety','gives them useful training','damages their health or interests','该词表示造成不利影响。')]});
D('harmless',{etymology:E('Harmless is formed from harm plus -less, meaning causing no harm or damage.','harmless'),contexts:[C('harmless.s1','动物观察','The wildlife officer explained that the small garden snake was harmless to people and asked the residents to leave it undisturbed.','野生动物管理员解释说，这条小花园蛇对人无害，并请居民不要打扰它。','The wildlife officer explained / that the small garden snake was harmless to people / and asked the residents / to leave it undisturbed.','harmless 表示不会造成伤害。','管理员判断蛇对人无害，因此让居民不去惊扰。')],mistakes:[M('The harmless cleaner caused severe burns and lasting lung damage whenever anyone touched or breathed near it.','The dangerous cleaner caused burns and lung damage when touched or inhaled.','造成严重灼伤和肺损害的清洁剂不可能无害。')],quiz:[Q('harmless',1,1,'A harmless insect?','does not cause injury or damage','always attacks people','is a type of handset','does not cause injury or damage','harmless 指无害的。'),Q('harmless',2,1,'Which action is harmless to a paper document?','placing it carefully in a dry folder','soaking it in acid','burning it','placing it carefully in a dry folder','妥善存放不会损坏文件。'),Q('harmless',3,1,'Harmless is formed with -less, meaning?','without or lacking harm','full of harm','able to cause harm','without or lacking harm','-less 表示“无、缺少”。','word-formation'),Q('harmless',4,1,'A harmless joke should?','not injure or seriously upset anyone','damage someone’s property','threaten a person’s safety','not injure or seriously upset anyone','无害的玩笑不应伤害他人。')]});
D('harmonic',{etymology:E('Harmonic comes through Latin harmonicus from Greek harmonikos, related to harmonia “joining or agreement.” It can name a frequency related by a whole-number multiple to a fundamental tone, or describe musical harmony.','harmonic'),contexts:[C('harmonic.s1','声学测量','The instrument detected a harmonic at three times the fundamental frequency, which helped the engineer identify vibration in the motor casing.','仪器检测到一个频率为基频三倍的谐波，帮助工程师识别电机外壳的振动。','The instrument detected a harmonic / at three times the fundamental frequency / which helped the engineer identify / vibration in the motor casing.','harmonic 在此是基频整数倍的频率，即谐波。','三倍基频符合 harmonic 的声学定义。')],mistakes:[M('The measured harmonic had a frequency of 2.4 times the fundamental but was described as a whole-number multiple.','The measured frequency was not a whole-number harmonic because 2.4 is not an integer multiple.','2.4 不是整数倍，不能按此定义称为 harmonic。')],quiz:[Q('harmonic',1,1,'A harmonic frequency is a whole-number multiple of?','a fundamental frequency','a person’s handedness','a county boundary','a fundamental frequency','s1 指基频的整数倍频率。'),Q('harmonic',2,2,'A harmonic musical interval is?','related to musical harmony','a fixed electrical wire','a hard hat','related to musical harmony','s2 指与和声或悦耳组合有关。'),Q('harmonic',3,1,'If a tone has a fundamental frequency of 100 Hz, a harmonic may be?','300 Hz','240 Hz','95 Hz','300 Hz','300 是基频的整数倍。'),Q('harmonic',4,2,'Which phrase uses harmonic as a musical adjective?','harmonic balance between the notes','harmonic damage to a handbag','harmonic number of bus stops','harmonic balance between the notes','和声平衡体现音乐形容词义。')]});
D('harmonica',{etymology:E('Harmonica was named from harmony, with the musical instrument name popularized for a small free-reed mouth organ. It is held in the hands and played by breathing through it.','harmonica'),contexts:[C('harmonica.s1','街头演奏','The musician carried a harmonica in his jacket pocket and played a blues melody by drawing and blowing air through its reeds.','音乐家把口琴放在夹克口袋里，通过吸气和吹气使簧片发声，演奏一段布鲁斯旋律。','The musician carried a harmonica in his jacket pocket / and played a blues melody / by drawing and blowing air / through its reeds.','harmonica 指手持、以呼吸吹吸发声的口琴。','吹吸气流使内部簧片振动，符合口琴演奏方式。')],mistakes:[M('She played the harmonica by striking its strings with a bow while holding it under her chin.','She played the violin by bowing its strings and used the harmonica by breathing through its reeds.','弓弦演奏属于小提琴，不是口琴。')],quiz:[Q('harmonica',1,1,'A harmonica is played by?','breathing through it','striking its piano keys','plucking long strings','breathing through it','口琴通过吹气和吸气演奏。'),Q('harmonica',2,1,'A harmonica is also called a?','mouth organ','hard hat','handout','mouth organ','harmonica 是口琴，也称 mouth organ。'),Q('harmonica',3,1,'What vibrates to make sound in a harmonica?','its reeds','a hammerhead shark','the player’s coat hanger','its reeds','口琴簧片在气流作用下振动。'),Q('harmonica',4,1,'Why is a harmonica easy to carry?','it is a small hand-held instrument','it is a large keyboard','it is built into every wall','it is a small hand-held instrument','口琴体积小，可随身携带。')]});
D('harmonious',{etymology:E('Harmonious is formed from harmony plus -ous. It describes sounds, colours, or parts that combine pleasantly and can describe friendly relations without serious conflict.','harmonious'),contexts:[C('harmonious.s2','社区协作','The two neighbourhood groups maintained a harmonious relationship by sharing the park schedule and resolving noise complaints through regular meetings.','两个社区团体通过共享公园安排并定期协商解决噪声投诉，保持了和睦关系。','The two neighbourhood groups maintained a harmonious relationship / by sharing the park schedule / and resolving noise complaints / through regular meetings.','harmonious 在此指群体关系和睦、没有严重冲突。','双方合作安排并协商解决问题，符合 s2。')],mistakes:[M('The groups had a harmonious relationship, although they refused to speak, repeatedly fought, and shared no decisions.','The groups had a hostile relationship because they repeatedly fought and refused to cooperate.','持续争吵、拒绝沟通与和睦关系相反。')],quiz:[Q('harmonious',1,1,'A harmonious colour scheme?','combines colours in a pleasing balance','uses random clashing colours','contains no colour at all','combines colours in a pleasing balance','s1 指颜色搭配协调悦目。'),Q('harmonious',2,2,'Harmonious neighbours?','live together without serious conflict','fight over every shared decision','never communicate','live together without serious conflict','s2 指关系和睦。'),Q('harmonious',3,1,'A harmonious musical passage has?','sounds that blend pleasantly','a loud siren over every note','no pattern or balance','sounds that blend pleasantly','悦耳协调的声音符合 s1。'),Q('harmonious',4,2,'Which arrangement supports a harmonious relationship?','listening and resolving disagreements fairly','refusing all discussion','spreading rumors about each other','listening and resolving disagreements fairly','协商解决分歧有助于和睦相处。')]});
D('harmonize',{etymology:E('Harmonize is formed from harmony plus -ize, a verb-forming suffix. It means bring things into agreement or make them fit together; in music it can mean add harmony.','harmonize'),contexts:[C('harmonize.s1','规则协调','The regional offices agreed to harmonize their reporting forms so that staff could compare the figures without converting different categories.','各地区办事处同意统一报告表格，使员工无需转换不同类别便能比较数据。','The regional offices agreed to harmonize their reporting forms / so that staff could compare the figures / without converting / different categories.','harmonize 在此表示使规则或格式彼此协调一致。','统一表格分类以方便比较，符合该动词义。')],mistakes:[M('The offices harmonized their forms by making each form use a different incompatible set of categories.','The offices harmonized their forms by adopting the same categories.','彼此不兼容的分类不会使表格协调一致。')],quiz:[Q('harmonize',1,1,'To harmonize two sets of rules is to?','bring them into agreement','make them contradict each other','store them in a hamper','bring them into agreement','harmonize 表示使一致、协调。'),Q('harmonize',2,1,'A company may harmonize procedures across offices to?','make them consistent','make them impossible to compare','remove every written rule','make them consistent','统一程序便于跨办公室协作。'),Q('harmonize',3,1,'In music, singers harmonize when they?','sing complementary notes together','speak one at a time with no pitch','repair a hard hat','sing complementary notes together','音乐中的 harmonize 可指加入和声。'),Q('harmonize',4,1,'The suffix -ize in harmonize helps form?','a verb meaning make or bring into a state','a noun naming a person','a plural form','a verb meaning make or bring into a state','-ize 常构成动词。','word-formation')]});
D('harmony',{etymology:E('Harmony comes through Old French harmonie from Latin harmonia and Greek harmonia, “joining or agreement.” It can mean peaceful agreement among people, a pleasing combination, or simultaneous musical notes.','harmony'),contexts:[C('harmony.s3','合唱排练','The choir held the final chord in close harmony, with the lower voices supporting the melody until the conductor lowered her hands.','合唱团以紧密和声保持最后一个和弦，低声部支撑旋律，直到指挥放下双手。','The choir held the final chord in close harmony / with the lower voices supporting the melody / until / the conductor lowered her hands.','harmony 在此指多个音同时发声形成的和声。','不同声部共同构成一个和弦，符合 s3。')],mistakes:[M('The choir sang in harmony while every singer performed a different unrelated tune at a different tempo.','The choir sang several coordinated parts that formed a harmony.','彼此无关且速度不同的曲调不能形成协调和声。')],quiz:[Q('harmony',1,1,'Harmony between neighbours means?','peaceful agreement','a severe argument','a physical injury','peaceful agreement','s1 指人与人之间和睦。'),Q('harmony',2,2,'A harmonious design has?','parts that combine in a pleasing way','pieces that clash without purpose','no relation among its colours','parts that combine in a pleasing way','s2 指事物协调悦目的组合。'),Q('harmony',3,3,'In music, harmony is?','notes sounded together as a combination','one note played with no other sound','a written handout','notes sounded together as a combination','s3 指同时发声的音的组合。'),Q('harmony',4,1,'A community meeting may promote harmony by?','helping residents resolve disagreements','encouraging groups to attack each other','preventing anyone from speaking','helping residents resolve disagreements','解决分歧有助于人际和睦。')]});

})();
